  'Un medio. Eso es un medio.': 'Un mig. Això és un mig.',
  'Se llama desfragmentar.': 'Es diu desfragmentar.',
  'No los matas. Los vuelves al sitio del que salieron.': 'No els mates. Els tornes al lloc d\'on van sortir.',
