  'Irune sentada. Pelo blanco, chaqueta gris, marca de plata al cuello.': 'Irune asseguda. Cabell blanc, jaqueta grisa, marca de plata al coll.',
  'Llegas. Pasa.': 'Arribes. Passa.',
  'Soy Irune. Esta es mi casa, y también la tuya ahora, si te lo tomas en serio.': 'Soc Irune. Aquesta és la meva casa, i també la teva ara, si t\'ho prens seriosament.',
