  'Primera. Aquí nadie sabe más de lo que sabe. Si alguien te dice que lo sabe todo, desconfía. Aunque sea yo.': 'Primera. Aquí ningú sap més del que sap. Si algú et diu que ho sap tot, desconfia. Encara que sigui jo.',
  'Segunda. Los Fragmentos no son enemigos. Son pedazos de algo que se rompió. Los desfragmentamos. Eso es todo.': 'Segona. Els Fragments no són enemics. Són trossos d\'alguna cosa que es va trencar. Els desfragmentem. Això és tot.',
  'Tercera. Si te cansas, paras. Si necesitas irte, te vas. Esto no es una cárcel.': 'Tercera. Si et canses, pares. Si necessites marxar, marxes. Això no és una presó.',
  'Vete con ella ya. Yo tengo cosas que hacer.': 'Vés amb ella ja. Jo tinc coses a fer.',
  'Al salir, Sora casi sin girarse:': 'En sortir, Sora gairebé sense girar-se:',
  'Cae bien, Irune. Cuando quiere.': 'Cau bé, Irune. Quan vol.',
