  'Pequeño.': 'Petit.',
  'Es Kurz. Lleva aquí más tiempo que yo. Es un Fragmento nombrado. No se disuelve — se retira y vuelve.': 'És Kurz. Fa més temps que jo que és aquí. És un Fragment anomenat. No es dissol — es retira i torna.',
  'Sirve para poneros a prueba. No es malo.': 'Serveix per posar-vos a prova. No és dolent.',
  'Pero es mejor que tú. Todavía.': 'Però és millor que tu. Encara.',
