  'Muy lento.': 'Molt lent.',
  'Otra vez mal.': 'Una altra vegada malament.',
  'Tenías que haberlo visto venir.': 'Ho havies d\'haver vist venir.',
  'Kurz se acerca. Calmo.': 'Kurz s\'acosta. Calmat.',
  'Ya está. No pasa nada.': 'Ja està. No passa res.',
  'Negro. La azotea vuelve. Sentado en el suelo. Kurz se aleja.': 'Negre. El terrat torna. Assegut a terra. Kurz s\'allunya.',
  'Sora se acerca. Tiende la mano.': 'Sora s\'acosta. Allarga la mà.',
