  'Puedes. No hoy. Pero puedes.': 'Pots. Avui no. Però pots.',
  'Vale. Vamos a descansar.': 'D\'acord. Anem a descansar.',
  'Otra noche. Punto elevado de la azotea. Otro aprendiz entrena a 30 metros.': 'Una altra nit. Punt elevat del terrat. Un altre aprenent entrena a 30 metres.',
  'Se mueve con soltura. No es el primer día que lo hace.': 'Es mou amb soltesa. No és el primer dia que ho fa.',
  'Ese es Kai.': 'Aquest és Kai.',
  'Lleva cuatro años entrenando.': 'Fa quatre anys que entrena.',
