  'Asiente a Sora — saludo profesional. A ti te mira un segundo. Sin sonrisa. Registrando.': 'Saluda Sora amb el cap — salutació professional. A tu et mira un segon. Sense somriure. Registrant.',
  'Sigue bajando.': 'Continua baixant.',
