  'Irune querrá verte.': 'Irune et voldrà veure.',
  'La azotea al atardecer. Por primera vez no es de noche.': 'El terrat al capvespre. Per primera vegada no és de nit.',
  'Hoy.': 'Avui.',
  'Hoy estás listo.': 'Avui estàs a punt.',
  'Silba. Kurz baja. La azotea tiembla un poco. 7/8 sobre él.': 'Xiula. Kurz baixa. El terrat tremola una mica. 7/8 sobre ell.',
  'Ah.': 'Ah.',
  'Te noto distinto.': 'Et noto diferent.',
  'Kurz se hace pequeño. Sube despacio.': 'Kurz es fa petit. Puja a poc a poc.',
  'Nos veremos cuando seas Iniciado.': 'Ens veurem quan siguis Iniciat.',
  'Sora asiente una vez, muy despacio.': 'Sora assenteix una vegada, molt a poc a poc.',
  'Ya está.': 'Ja està.',
  'Ya eres algo más que un aprendiz.': 'Ja ets alguna cosa més que un aprenent.',
  'Mira hacia la puerta. Irune está ahí. Asiente de lejos. Entra.': 'Mira cap a la porta. Irune hi és. Assenteix de lluny. Entra.',
  'Otra vez. La semana que viene.': 'Una altra vegada. La setmana que ve.',
  'Mañana.': 'Demà.',
  'Estabas cerca.': 'Hi eres a prop.',
  'La sala de Irune. La luz más cálida que la primera vez.': 'La sala d\'Irune. La llum més càlida que la primera vegada.',
  'Siéntate.': 'Seu.',
  'No te voy a felicitar. Sora tampoco. No es nuestro estilo.': 'No et felicitaré. Sora tampoc. No és el nostre estil.',
  'Pero lo que has hecho es real.': 'Però el que has fet és real.',
  'La gente habla de rangos como si fueran diplomas. No lo son. Son responsabilidades.': 'La gent parla de rangs com si fossin diplomes. No ho són. Són responsabilitats.',
  'Ahora eres Aprendiz II. Eso quiere decir que puedes salir del Edificio de los Tejados sin que Sora vaya detrás.': 'Ara ets Aprenent II. Això vol dir que pots sortir de l\'Edifici dels Terrats sense que Sora vagi al darrere.',
  'Vas a hacerte amigos, enemigos, dudas. Sobre todo dudas.': 'Et faràs amics, enemics, dubtes. Sobretot dubtes.',
  'Mañana puedes bajar a los Canales. Si quieres. O no. Tú decides.': 'Demà pots baixar als Canales. Si vols. O no. Tu decideixes.',
  'Y una cosa más.': 'I una cosa més.',
  'Hace mucho que no ponía una marca de Aprendiz II.': 'Fa molt que no posava una marca d\'Aprenent II.',
  'Silencio. Irune deja respirar la frase un momento largo.': 'Silenci. Irune deixa respirar la frase un moment llarg.',
  'Me alegro de que vuelva a haber alguien que la merezca.': 'M\'alegro que torni a haver-hi algú que la mereixi.',
  'Te pone una marca plateada al cuello. Una cuerda fina. Frío al principio, luego templada.': 'Et posa una marca platejada al coll. Una corda fina. Freda al principi, després temperada.',
  'Bienvenido, Aprendiz II.': 'Benvingut, Aprenent II.',
  'Ya puedes irte. Duerme.': 'Ja te\'n pots anar. Dorm.',
  'Borde de la azotea. Sora sentada con las piernas colgando, sin miedo. Mira al norte.': 'Vora del terrat. Sora asseguda amb les cames penjant, sense por. Mira al nord.',
  'Abajo, los Canales: puentes pequeños iluminados, reflejos amarillos en el agua. Una ciudad dentro de la ciudad.': 'A baix, els Canales: ponts petits il·luminats, reflexos grocs a l\'aigua. Una ciutat dins de la ciutat.',
  'Allí vas a ir mañana.': 'Allà hi aniràs demà.',
  'Los Canales.': 'Els Canales.',
  'Maestro Rexán.': 'Mestre Rexán.',
  'Va a caerte bien. Es el tipo más simpático de la orden. No te fíes del todo — lo usa.': 'Et caurà bé. És el tipus més simpàtic de l\'orde. No te\'n fiïs del tot — ho fa servir.',
  'Tiene una cojera. No preguntes por ella.': 'Té una coixesa. No preguntis per ella.',
  'Algún día te lo contará. O no. Ya verás.': 'Algun dia t\'ho explicarà. O no. Ja veuràs.',
  'Tienes que ir solo. Yo te esperaré aquí.': 'Has d\'anar-hi sol. Jo t\'esperaré aquí.',
  'Sí. Solo.': 'Sí. Sol.',
  'No te asustes. Rexán es buena gente. Y tú ya no eres tan nuevo.': 'No t\'espantis. Rexán és bona gent. I tu ja no ets tan nou.',
  'Sora saca una pequeña brújula de bolsillo. No mágica. Solo una brújula.': 'Sora treu una brúixola petita de butxaca. No màgica. Només una brúixola.',
  'Toma. Era mía cuando empecé aquí.': 'Té. Era meva quan vaig començar aquí.',
  'Devuélvemela cuando vuelvas.': 'Torna-me-la quan tornis.',
  'Mira otra vez hacia los Canales. Viento. Fundido lento.': 'Mira un altre cop cap als Canales. Vent. Fos lent.',
  'HASTA MAÑANA': 'FINS DEMÀ',
  'Escalera que baja del Edificio de los Tejados. Niebla baja en las calles.': 'Escala que baixa de l\'Edifici dels Terrats. Boira baixa als carrers.',
  'Ya.': 'Ja.',
  'Vete.': 'Vés-te\'n.',
  'Si te pasa algo, vuelves corriendo. No te hagas el valiente.': 'Si et passa res, tornes corrent. No et facis el valent.',
  'Y si tardas mucho, voy yo.': 'I si trigues molt, hi vaig jo.',
  'Calles estrechas. Una pareja en un portal. Un gato dormido. Un Fragmento tonto se disuelve solo.': 'Carrers estrets. Una parella en un portal. Un gat adormit. Un Fragment ximple es dissol sol.',
  'La luz cambia — más amarilla. El agua aparece entre las piedras.': 'La llum canvia — més groga. L\'aigua apareix entre les pedres.',
  'BARRIO DE LOS CANALES': 'BARRI DELS CANALES',
  'Al otro lado de un puente, un hombre mayor sentado en un saliente. Lee. Levanta la vista. Sonríe.': 'A l\'altre costat d\'un pont, un home gran assegut en un sortint. Llegeix. Aixeca la vista. Somriu.',
  'Se levanta. Cojea. No lo esconde ni lo señala.': 'S\'aixeca. Coixeja. No ho amaga ni ho assenyala.',
  'A ver, a ver.': 'A veure, a veure.',
  'Primera sonrisa abierta de un adulto en el juego.': 'Primer somriure obert d\'un adult al joc.',
  'Tú eres el que Sora manda.': 'Tu ets el que Sora envia.',
  'Tiende la mano.': 'Allarga la mà.',
  'Rexán. Maestro de los Canales, dicen. Yo me llamo Rexán. Sin más.': 'Rexán. Mestre dels Canales, diuen. Jo em dic Rexán. Sense més.',
  'Tú ya sabes lo que es un Fragmento. Sabes sumar trozos cuando son iguales. Ya eres Aprendiz II. No está mal.': 'Tu ja saps què és un Fragment. Saps sumar trossos quan són iguals. Ja ets Aprenent II. No està malament.',
  'Aquí vas a aprender algo distinto.': 'Aquí aprendràs alguna cosa diferent.',
  'Señala el canal. Dos Fragmentos flotan sobre el agua: 1/2 y 2/4.': 'Assenyala el canal. Dos Fragments floten sobre l\'aigua: 1/2 i 2/4.',
  '¿Cuál es más grande?': 'Quin és més gran?',
  'Mm. ¿Seguro? Míralos otra vez. Mira el agua.': 'Mm. Segur? Mira\'ls una altra vegada. Mira l\'aigua.',
  'Bien, {nombre}. Bien.': 'Bé, {nombre}. Bé.',
  'Los dos Fragmentos orbitan despacio y se fusionan en uno.': 'Els dos Fragments orbiten a poc a poc i es fusionen en un.',
  'Son la misma cosa. Con nombres distintos.': 'Són la mateixa cosa. Amb noms diferents.',
  'Un medio. Dos cuartos. Mismo trozo de mundo.': 'Un mig. Dos quarts. Mateix tros de món.',
  'Eso se llama equivaler.': 'Això es diu equivaler.',
  'Toda verdad tiene otra forma igualmente verdadera.': 'Tota veritat té una altra forma igualment vertadera.',
  'Es lo que aprendes aquí. Lo demás viene después.': 'És el que aprens aquí. La resta ve després.',
  'Vamos. Te enseño el barrio.': 'Anem. T\'ensenyo el barri.',
  'Callejón junto al canal. Dos Fragmentos emergen a la vez, con el mismo halo: 3/4 y 6/8.': 'Carreró al costat del canal. Dos Fragments emergeixen alhora, amb la mateixa aurèola: 3/4 i 6/8.',
  'Fragmentos Espejo.': 'Fragments Mirall.',
  'Se llaman así porque van en pareja. Uno parece el reflejo del otro.': 'Es diuen així perquè van en parella. Un sembla el reflex de l\'altre.',
  'Y casi siempre lo es.': 'I gairebé sempre ho és.',
  'Míralos bien, {nombre}. ¿Son equivalentes?': 'Mira\'ls bé, {nombre}. Són equivalents?',
  'Tres de cuatro. Seis de ocho. Simplifica seis de ocho y tienes tres de cuatro.': 'Tres de quatre. Sis de vuit. Simplifica sis de vuit i tens tres de quatre.',
  'Cuando encuentres dos así, los emparejas y se disuelven juntos. Es el gesto más limpio que puedes hacer.': 'Quan en trobis dos així, els emparelles i es dissolen junts. És el gest més net que pots fer.',
  'A veces no son equivalentes. Entonces tienes que reconocerlo y atacar por separado. No pasa nada.': 'A vegades no són equivalents. Llavors ho has de reconèixer i atacar per separat. No passa res.',
  'Si los emparejas mal, hacen ruido. Los oyes.': 'Si els emparelles malament, fan soroll. Els sents.',
  'Te guiña un ojo.': 'Et fa l\'ullet.',
  'Vas a aprender a oírlos.': 'Aprendràs a sentir-los.',
  'Callejón. Pared vieja con una pintada reciente: un círculo roto con cuatro líneas hacia fuera.': 'Carreró. Paret vella amb una pintada recent: un cercle trencat amb quatre línies cap enfora.',
  'Debajo, en letra temblorosa: "El uno era la cárcel."': 'A sota, amb lletra tremolosa: "L\'u era la presó."',
  'Vámonos, {nombre}.': 'Anem, {nombre}.',
  'Pintadas. No importantes.': 'Pintades. No importants.',
  'Porque algunos piensan así. Vamos.': 'Perquè alguns pensen així. Som-hi.',
  'No gira la cabeza hacia la pintada. Su voz no tiene miedo. Tiene cansancio.': 'No gira el cap cap a la pintada. La seva veu no té por. Té cansament.',
  'Terraza de un bar cerrado. Sillas apiladas. Dos monedas antiguas en la mesa.': 'Terrassa d\'un bar tancat. Cadires apilades. Dues monedes antigues a la taula.',
  'Oye.': 'Escolta.',
  '¿Sora te ha hablado de Zafrán alguna vez?': 'Sora t\'ha parlat mai de Zafrán?',
  'Niegas con la cabeza.': 'Negues amb el cap.',
  'Bueno. Yo te digo el nombre al menos.': 'Bé. Jo almenys et dic el nom.',
  'Es un Fragmento grande. Muy viejo. Vive por aquí.': 'És un Fragment gran. Molt vell. Viu per aquí.',
  'Ahora mismo no te preocupes de él. No te va a ver. No te tiene que ver.': 'Ara mateix no te n\'amoïnis. No et veurà. No t\'ha de veure.',
  'Pero si alguna vez oyes un silbido largo y raro por la noche, de los canales... te vuelves al Edificio de los Tejados.': 'Però si algun cop sents un xiulet llarg i estrany de nit, des dels Canales... te\'n tornes a l\'Edifici dels Terrats.',
  'Sin pensarlo. ¿De acuerdo?': 'Sense pensar-t\'ho. D\'acord?',
  'Porque sí. Confía en mí una vez y hazme caso. Solo una vez.': 'Perquè sí. Confia en mi una vegada i fes-me cas. Només una vegada.',
  'Bien. Gracias.': 'Bé. Gràcies.',
  '¿Has visto la luna esta noche? Solo una. Qué pena.': 'Has vist la lluna aquesta nit? Només una. Quina llàstima.',
  'Puente grande. Niebla leve. Dos Fragmentos flotan unidos por una línea de luz densa: 1/3 y 1/4.': 'Pont gran. Boira lleu. Dos Fragments suren units per una línia de llum densa: 1/3 i 1/4.',
  'Duales.': 'Duals.',
  'Esto es lo nuevo. Esto es lo que querías ver.': 'Això és el nou. Això és el que volies veure.',
  'Con los Duales, no puedes atacar a uno solo. Están enganchados.': 'Amb els Duals, no pots atacar-ne només un. Estan enganxats.',
  'Tienes que unirlos primero. Volverlos un solo Fragmento. Y entonces los atacas.': 'Els has d\'unir primer. Convertir-los en un sol Fragment. I llavors els ataques.',
  'Para unirlos, tienen que hablar el mismo idioma. Mismo denominador.': 'Per unir-los, han de parlar el mateix idioma. Mateix denominador.',
  'Un tercio y un cuarto no hablan el mismo idioma. Mira.': 'Un terç i un quart no parlen el mateix idioma. Mira.',
  'Los Fragmentos se rozan. Un chirrido desagradable. Rebotan.': 'Els Fragments es freguen. Un grinyol desagradable. Reboten.',
  '¿Lo oyes? Así suena cuando los unes mal.': 'Ho sents? Així sona quan els uneixes malament.',
  'Busca un número que sea múltiplo de los dos. De tres y de cuatro.': 'Busca un nombre que sigui múltiple dels dos. De tres i de quatre.',
  'Doce. 1/3 se vuelve 4/12. 1/4 se vuelve 3/12. Se funden en 7/12.': 'Dotze. 1/3 es torna 4/12. 1/4 es torna 3/12. Es fonen en 7/12.',
  'Doce es lo más pequeño que los dos comparten. Se llama mínimo común múltiplo. MCM, para ir rápido.': 'Dotze és el més petit que els dos comparteixen. Es diu mínim comú múltiple. MCM, per anar ràpid.',
  'Ahora ya es un Fragmento normal. Atácalo.': 'Ara ja és un Fragment normal. Ataca\'l.',
  'Rexán sonríe de medio lado.': 'Rexán somriu de mig costat.',
  'Esto es lo más bonito que se aprende aquí.': 'Això és el més bonic que s\'aprèn aquí.',
  'En serio. Cuando esto lo tienes, el resto es juego.': 'De debò. Quan tens això, la resta és joc.',
  'Muelle pequeño al borde de un canal ancho. Pies casi tocando el agua.': 'Moll petit a la vora d\'un canal ample. Peus gairebé tocant l\'aigua.',
  'Un minuto de silencio. Solo el agua.': 'Un minut de silenci. Només l\'aigua.',
  'Yo me formé en el Puerto, ¿sabes?': 'Jo em vaig formar al Port, saps?',
  'Oryn me entrenó. Hace muchos años. Él era joven todavía, como Sora ahora.': 'L\'Oryn em va entrenar. Fa molts anys. Ell encara era jove, com la Sora ara.',
  'Desde entonces, el agua me gusta.': 'Des de llavors, m\'agrada l\'aigua.',
  'Tira una piedrita al agua.': 'Tira una pedreta a l\'aigua.',
  'Cuando me pasó lo de la pierna, hace ya, volví al Puerto a recuperar.': 'Quan em va passar el de la cama, fa temps, vaig tornar al Port a recuperar-me.',
  'Estuve un año entero viendo el agua desde un muelle como este.': 'Vaig estar un any sencer mirant l\'aigua des d\'un moll com aquest.',
  'Cuando pude caminar otra vez, me preguntaron si quería volver a ser Maestro.': 'Quan vaig poder caminar de nou, em van preguntar si volia tornar a ser Mestre.',
  'Les dije que sí, pero aquí, en los Canales. Porque los canales tienen agua también, y no son el mar.': 'Els vaig dir que sí, però aquí, als Canales. Perquè els canals també tenen aigua, i no són el mar.',
  'El mar acuerda. Los canales olvidan.': 'El mar recorda. Els canals obliden.',
  'Eso no lo entiendes todavía. No importa.': 'Això encara no ho entens. No importa.',
  'Otro día, {nombre}. Hoy no.': 'Un altre dia, {nombre}. Avui no.',
  'Sora no baja al Puerto. No le gusta el agua. Aún.': 'La Sora no baixa al Port. No li agrada l\'aigua. Encara.',
  'Tira otra piedrita. Se levanta apoyándose en el bastón.': 'Tira una altra pedreta. S\'aixeca recolzant-se al bastó.',
  'Venga. Antes de que nos durmamos los dos.': 'Va. Abans no ens adormim tots dos.',
  'Esquina cerca del Edificio de los Tejados. Una chica de tu edad, mochila cruzada.': 'Cantonada a prop de l\'Edifici dels Terrats. Una noia de la teva edat, motxilla creuada.',
  'Hola.': 'Hola.',
  '¿Tú también eres nuevo?': 'Tu també ets nou?',
  'Soy Ari. Llegué hace seis meses.': 'Sóc l\'Ari. Vaig arribar fa sis mesos.',
  'Poco hablador, tú. Me gusta.': 'Poc xerraire, tu. M\'agrada.',
  'Oye. Estoy con el Maestro Vadic. Industria. ¿Tú?': 'Escolta. Estic amb el Mestre Vadic. Indústria. Tu?',
  'Ah, Rexán. Me cae bien. Luego te caerá a ti.': 'Ah, Rexán. M\'agrada. Després t\'agradarà a tu.',
  'Vale, vale, no preguntaba por preguntar. Solo curiosidad.': 'D\'acord, d\'acord, no preguntava per preguntar. Només curiositat.',
  'Bueno. Me tengo que ir. Mis padres no saben que ando por aquí a esta hora.': 'Bé. Me n\'haig d\'anar. Els meus pares no saben que sóc per aquí a aquesta hora.',
  'Nos vemos por los tejados.': 'Ens veiem pels terrats.',
  'Echa a correr. Se gira al correr:': 'Es posa a córrer. Es gira mentre corre:',
  'No te metas con los Espejo los lunes, eh. No sé por qué pero los lunes son raros.': 'No et fiquis amb els Mirall els dilluns, eh. No sé per què però els dilluns són estranys.',
  'Mitad de un entrenamiento con Rexán. Un silbido largo y grave rompe el aire.': 'A mig entrenament amb Rexán. Un xiulet llarg i greu trenca l\'aire.',
  'Tres segundos. Un quiebro extraño al final. Ni pájaro ni sirena.': 'Tres segons. Un trencament estrany al final. Ni ocell ni sirena.',
  'Rexán se queda completamente quieto. Deja caer el bastón sin darse cuenta. Lo recoge despacio.': 'Rexán es queda completament quiet. Deixa caure el bastó sense adonar-se\'n. El recull a poc a poc.',
  'Se acabó por hoy.': 'S\'ha acabat per avui.',
  'Intenta sonreír. No lo consigue del todo.': 'Intenta somriure. No ho aconsegueix del tot.',
  'Vete al Edificio de los Tejados. Ahora. Despacio pero ya.': 'Ves a l\'Edifici dels Terrats. Ara. A poc a poc però ja.',
  'Y no pasas por la calle del mercado nocturno.': 'I no passis pel carrer del mercat nocturn.',
  'Dile a Irune que he oído a Zafrán.': 'Digues a la Irune que he sentit Zafrán.',
  'Se va en dirección contraria. La cojera se nota más. Calles silenciosas. Puestos cerrando antes. Ventanas apagándose al pasar.': 'Se\'n va en direcció contrària. La coixesa es nota més. Carrers silenciosos. Parades tancant abans. Finestres apagant-se en passar.',
  'Al subir al Edificio, Sora en la puerta.': 'En pujar a l\'Edifici, Sora a la porta.',
  'Pasa. Irune quiere verte.': 'Entra. Irune vol veure\'t.',
  'Azotea al amanecer. Sora con cazadora gruesa y una bolsa pequeña cruzada al cuerpo.': 'Terrat a l\'alba. Sora amb caçadora gruixuda i una bossa petita creuada al cos.',
  'Hoy voy contigo.': 'Avui vinc amb tu.',
  'No al entrenamiento. Al combate.': 'No a l\'entrenament. Al combat.',
  'Rexán no puede. No debe. Así que voy yo.': 'Rexán no pot. No ha de fer-ho. Així que hi vaig jo.',
  'Irune aparece en la puerta sin cruzar. Asiente a Sora. Desaparece.': 'Irune apareix a la porta sense travessar-la. Assenteix a Sora. Desapareix.',
  'Zafrán es un Fragmento Dual muy viejo. Enorme. Vive entre los canales, en la zona más profunda del distrito.': 'Zafrán és un Fragment Dual molt vell. Enorme. Viu entre els canals, a la zona més profunda del districte.',
  'No ataca todo el tiempo. A veces está dormido años. Y de vez en cuando sale.': 'No ataca tota l\'estona. De vegades dorm anys. I de tant en tant surt.',
  'La última vez fue hace dos semanas. Un ruido en el mercado. No fue mucho. Rexán lo contuvo.': 'L\'última vegada va ser fa dues setmanes. Un soroll al mercat. No va ser gran cosa. Rexán el va contenir.',
  'La anterior, hace veinte años, le dejó la pierna como la tiene.': 'L\'anterior, fa vint anys, li va deixar la cama com la té.',
  'Esta no la aguanta solo. Irune no quiere que vaya él. Voy yo.': 'Aquesta no l\'aguanta sol. Irune no vol que hi vagi ell. Hi vaig jo.',
  'Y tú.': 'I tu.',
  'Primera mirada sin distancia.': 'Primera mirada sense distància.',
  'No porque seas bueno. Porque es tu distrito ahora. Tienes que verlo con tus ojos.': 'No perquè siguis bo. Perquè ara és el teu districte. L\'has de veure amb els teus ulls.',
  'Te quedas atrás. Atacas cuando te digo. No haces nada que no te diga.': 'Et quedes darrere. Ataques quan t\'ho digui. No fas res que no et digui.',
  '¿Vale?': 'D\'acord?',
  'Mientras me hagas caso, sí.': 'Mentre em facis cas, sí.',
  'Vale. Vamos.': 'D\'acord. Anem.',
  'La parte más profunda y vieja del Barrio. Plaza circular pequeña. Pozo viejo de piedra cubierto con reja oxidada.': 'La part més profunda i vella del Barri. Plaça circular petita. Pou vell de pedra cobert amb reixa rovellada.',
  'Aquí.': 'Aquí.',
  'Sale de ahí.': 'Surt d\'aquí.',
  'Cuando salga, será grande. Más que todo lo que has visto.': 'Quan surti, serà gran. Més que tot el que has vist.',
  'Va a tener dos valores distintos. Denominadores diferentes. Tú y yo los vamos a fusionar.': 'Tindrà dos valors diferents. Denominadors diferents. Tu i jo els fusionarem.',
  'Yo uno. Tú otro.': 'Jo un. Tu un altre.',
  'Como en los puentes con Rexán.': 'Com als ponts amb Rexán.',
  'Si fallas, no pasa nada. Yo fusiono los dos. Pero va a tardar más. Y va a doler más.': 'Si falles, no passa res. Jo fusiono els dos. Però trigarà més. I farà més mal.',
  'Atrás.': 'Enrere.',
  'La reja tiembla. Salta. Emerge Zafrán: altura de una casa, dos cuerpos conectados por una línea de luz densa.': 'La reixa tremola. Salta. Emergeix Zafrán: alçada d\'una casa, dos cossos connectats per una línia de llum densa.',
  'Izquierdo 5/7. Derecho 3/11. Cuerpo agrietado en patrones viejos.': 'Esquerre 5/7. Dret 3/11. Cos esquerdat en patrons vells.',
  'Un sonido vibrante hace temblar las piedras. La respiración de Sora se acelera. Rabia, no miedo.': 'Un so vibrant fa tremolar les pedres. La respiració de Sora s\'accelera. Ràbia, no por.',
  'Hola, Zafrán.': 'Hola, Zafrán.',
  'Sí. Me acuerdo.': 'Sí. Me\'n recordo.',
  'Saca una marca pequeña del bolsillo. Vieja. Oxidada. Distinta de la del cuello. La aprieta.': 'Treu una marca petita de la butxaca. Vella. Rovellada. Diferent de la del coll. L\'estreny.',
  'Esta es por Rexán.': 'Aquesta és per Rexán.',
  'Zafrán se hace pequeño. Al llegar a 1/16, escapa al pozo con un chirrido. La reja cae con un golpe seco.': 'Zafrán es fa petit. En arribar a 1/16, escapa al pou amb un grinyol. La reixa cau amb un cop sec.',
  'Silencio. Sora se limpia la cara con el dorso de la mano.': 'Silenci. Sora s\'eixuga la cara amb el dors de la mà.',
  'Se va.': 'Se\'n va.',
  'Pero le hemos hecho daño.': 'Però li hem fet mal.',
  'Algo en su cara más abierto que nunca lo has visto.': 'Alguna cosa a la seva cara més oberta del que has vist mai.',
  'Lo has hecho bien.': 'Ho has fet bé.',
  'Muy bien, {nombre}.': 'Molt bé, {nombre}.',
  'Sora sentada en el suelo contra el pozo. Mano en la rodilla izquierda.': 'Sora asseguda a terra contra el pou. Mà al genoll esquerre.',
  'No es grave.': 'No és greu.',
  'Solo el golpe. Mañana estará.': 'Només el cop. Demà estarà.',
  'Saca la pequeña marca vieja. La mira. La aprieta.': 'Treu la petita marca vella. La mira. L\'estreny.',
  'Esta era de alguien.': 'Aquesta era d\'algú.',
  'De mi maestra. Antes de Irune.': 'De la meva mestra. Abans de la Irune.',
  'Lo mismo que a Rexán, más o menos. Peor.': 'El mateix que a Rexán, més o menys. Pitjor.',
  'No. Eso fue otra cosa. Otra ciudad.': 'No. Allò va ser una altra cosa. Una altra ciutat.',
  'Gracias.': 'Gràcies.',
  'Ayúdame a levantarme.': 'Ajuda\'m a aixecar-me.',
  'Acepta tu mano más tiempo del necesario. Cojea dos o tres pasos. Recupera su ritmo.': 'Accepta la teva mà més temps del necessari. Coixeja dos o tres passos. Recupera el seu ritme.',
  'Al volver al Edificio de los Tejados, Rexán está apoyado en el muro de la entrada con el bastón.': 'En tornar a l\'Edifici dels Terrats, Rexán està recolzat al mur de l\'entrada amb el bastó.',
  'Sora se queda atrás dando espacio.': 'Sora es queda darrere donant espai.',
  'A ver. Enséñame.': 'A veure. Ensenya\'m.',
  'Enseñas la marca de Aprendiz II. Tiene ahora un pequeño filete azul — señal de haber sobrevivido a un combate con un Fragmento nombrado.': 'Ensenyes la marca d\'Aprenent II. Ara té una petita franja blava — senyal d\'haver sobreviscut a un combat amb un Fragment anomenat.',
  'Bonita.': 'Bonica.',
  'La mía también la tiene.': 'La meva també la té.',
  'Se abre el cuello. Su marca con varios filetes azules, algunos viejos, uno muy desteñido.': 'Es descorda el coll. La seva marca amb diverses franges blaves, algunes velles, una molt descolorida.',
  'Sora.': 'Sora.',
  'Rexán.': 'Rexán.',
  'Sube. Irune quiere verte.': 'Puja. Irune vol veure\'t.',
  'Y duerme, {nombre}. Mañana es otro día y hoy ya estuvo.': 'I dorm, {nombre}. Demà és un altre dia i avui ja ha estat.',
  'Al entrar, Rexán y Sora se quedan fuera juntos. Sin hablar. Solo estando.': 'En entrar, Rexán i Sora es queden fora junts. Sense parlar. Només estant.',
  'Azotea. Borde norte. Sora con las piernas colgando, como al final del Arco 1. La niebla disipada, luces reflejadas en el agua.': 'Terrat. Vora nord. Sora amb les cames penjant, com al final de l\'Arc 1. La boira dissipada, llums reflectides a l\'aigua.',
  'Un minuto de silencio.': 'Un minut de silenci.',
  'Cuando era pequeña, en mi ciudad...': 'Quan era petita, a la meva ciutat...',
  '...tenía una ventana que daba a un canal.': '...tenia una finestra que donava a un canal.',
  'Se parece a estos.': 'S\'assembla a aquests.',
  'Mirada breve. Vuelve al paisaje. Primera vez que menciona su ciudad sin cortar.': 'Mirada breu. Torna al paisatge. Primera vegada que esmenta la seva ciutat sense tallar-se.',
  'No es importante. No sé por qué lo he dicho.': 'No és important. No sé per què ho he dit.',
  'Mañana, si quieres, puedes bajar al Mercado. Conocer a Naini.': 'Demà, si vols, pots baixar al Mercado. Conèixer la Naini.',
  'Yo no voy. Ella y yo ya nos conocemos.': 'Jo no hi vaig. Ella i jo ja ens coneixem.',
  'Pero tú vas a querer ir. Te va a caer bien.': 'Però tu hi voldràs anar. T\'agradarà.',
  'La ciudad ya es tuya. Todos los distritos.': 'La ciutat ja és teva. Tots els districtes.',
  'Bueno. Casi todos. La Montaña no.': 'Bé. Gairebé tots. La Montaña no.',
  'Segunda media sonrisa de Sora.': 'Segon mig somriure de Sora.',
  'Aún.': 'Encara.',
  'Portón alto iluminado. Una explosión de luz, sonido y olor al cruzarlo.': 'Portó alt il·luminat. Una explosió de llum, so i olor en travessar-lo.',
  '¡Qué bueno verte!': 'Que bo veure\'t!',
  'Soy Naini. Maestra del Mercado. Aunque aquí casi todos me llaman Naini a secas.': 'Sóc la Naini. Mestra del Mercado. Tot i que aquí gairebé tothom em diu Naini i prou.',
  'Iniciado, ¿eh? Pues venga. Pasa, pasa. Te cuento.': 'Iniciat, eh? Doncs au. Entra, entra. T\'ho explico.',
  'Fragmentos silvestres flotan entre la gente sin alarma.': 'Fragments silvestres suren entre la gent sense alarma.',
  'El Mercado es distinto. Aquí los Fragmentos no son enemigos todo el rato. Son valor en circulación.': 'El Mercado és diferent. Aquí els Fragments no són enemics tota l\'estona. Són valor en circulació.',
  '¿Tú has hecho alguna vez un trueque?': 'Tu has fet mai un bescanvi?',
  'Vale. Entonces ya medio entiendes.': 'D\'acord. Llavors ja ho entens a mitges.',
  'Pues lo vas a hacer hoy.': 'Doncs ho faràs avui.',
  'Aquí se cambia una cosa por otra. Un Fragmento por tres. Tres por uno. Porcentajes. Proporciones. Eso es lo que vas a aprender aquí.': 'Aquí es canvia una cosa per una altra. Un Fragment per tres. Tres per un. Percentatges. Proporcions. Això és el que aprendràs aquí.',
  'Y también vas a aprender a distinguir un trueque honesto de uno que no lo es.': 'I també aprendràs a distingir un bescanvi honest d\'un que no ho és.',
  'Pero eso ya es más adelante. Ven.': 'Però això ja serà més endavant. Vine.',
  'Puesto grande de frutas. 15 manzanas rojas y 10 amarillas.': 'Parada gran de fruita. 15 pomes vermelles i 10 grogues.',
  'Si te llevas un tercio de las rojas y la mitad de las amarillas, ¿cuántas en total?': 'Si t\'emportes un terç de les vermelles i la meitat de les grogues, quantes en total?',
  'No. Un tercio de 15 son 5. La mitad de 10 son 5.': 'No. Un terç de 15 són 5. La meitat de 10 són 5.',
  'Justo. 5 y 5.': 'Just. 5 i 5.',
  'Demasiadas. Un tercio de 15 son 5. La mitad de 10 son 5.': 'Massa. Un terç de 15 són 5. La meitat de 10 són 5.',
  '¿Y qué porcentaje del total son tus 10 manzanas? El total era 25.': 'I quin percentatge del total són les teves 10 pomes? El total era 25.',
  'No. 10 de 25. Diez de veinticinco.': 'No. 10 de 25. Deu de vint-i-cinc.',
  '40%. Justo.': '40 %. Just.',
  'Casi. 10 de 25 no es la mitad.': 'Quasi. 10 de 25 no és la meitat.',
  'Te pone dos manzanas en la mano. Le guiña un ojo a la vendedora.': 'Et posa dues pomes a la mà. Pica l\'ullet a la venedora.',
  'Aquí nadie te enseña nada gratis. Pero todo se aprende.': 'Aquí ningú no t\'ensenya res de franc. Però tot s\'aprèn.',
  'Esa es la regla del Mercado. Nada gratis. Pero todo posible.': 'Aquesta és la regla del Mercado. Res de franc. Però tot possible.',
  'Plaza lateral del Mercado. Kai. Más filetes azules en su marca de Aprendiz.': 'Plaça lateral del Mercado. Kai. Més franges blaves a la seva marca d\'Aprenent.',
  'Hombre.': 'Home.',
  'Me dijeron que habías bajado a ver a Naini.': 'M\'han dit que havies baixat a veure la Naini.',
  'Interesante.': 'Interessant.',
  'Oye, oye, tranquilo. Solo te saludaba.': 'Ei, ei, tranquil. Només et saludava.',
  'Vale. Tú mandas.': 'D\'acord. Tu manes.',
  'Oye. He oído lo de Zafrán.': 'Escolta. He sentit el de Zafrán.',
  'No todo el mundo sobrevive a su primer Fragmento nombrado.': 'No tothom sobreviu al seu primer Fragment anomenat.',
  'Yo conmigo el mío... todavía no lo vi.': 'Jo amb el meu... encara no l\'he vist.',
  'Bueno. Es lo que hay.': 'Bé. És el que hi ha.',
  'Si un día te aburres de entrenar con señores mayores, podemos combatir.': 'Si un dia t\'avorreixes d\'entrenar amb senyors grans, podem combatre.',
  'Tú contra mí. Nada oficial. Solo para ver.': 'Tu contra mi. Res oficial. Només per veure.',
  'Ari se acerca. Kai ya no está. Te ofrece un refresco.': 'L\'Ari s\'acosta. Kai ja no hi és. T\'ofereix un refresc.',
  'Toma.': 'Té.',
  'No te va a hablar en un tiempo.': 'No et parlarà durant un temps.',
  'Es así.': 'És així.',
  'Cuando yo le gané a Elen hace tres meses, estuvo desaparecida dos semanas. Ahora somos colegas.': 'Quan jo vaig guanyar a l\'Elen fa tres mesos, va estar desapareguda dues setmanes. Ara som col·legues.',
  'Déjale espacio.': 'Deixa-li espai.',
  'Tengo que volver con Vadic. Industria. Si bajas alguna vez, me avisas.': 'He de tornar amb Vadic. Indústria. Si baixes algun dia, m\'avises.',
  'Se gira al irse.': 'Es gira en marxar.',
  'Por cierto, has estado bien.': 'Per cert, has estat bé.',
  'Galpón de ladrillo rojo. Luz gris. Un hombre mide algo con un calibre. No levanta la vista.': 'Nau de maó vermell. Llum gris. Un home mesura alguna cosa amb un calibre. No aixeca la vista.',
  'Un momento.': 'Un moment.',
  'Anota. Guarda el calibre. Ahora mira.': 'Apunta. Desa el calibre. Ara mira.',
  'Vadic.': 'Vadic.',
  '¿Nombre?': 'Nom?',
  'Dices tu nombre. Asiente una vez.': 'Dius el teu nom. Assenteix una vegada.',
  'Esto mide 2,34 metros. ¿Cuántos centímetros son?': 'Això fa 2,34 metres. Quants centímetres són?',
  'No. Un metro son cien centímetros.': 'No. Un metre són cent centímetres.',
  'Correcto.': 'Correcte.',
  'No. Eso serían milímetros.': 'No. Això serien mil·límetres.',
  '¿Y en milímetros?': 'I en mil·límetres?',
  'No. Diez veces más.': 'No. Deu vegades més.',
  'Aprendiz tres, Iniciado II. Bien para trabajar aquí.': 'Aprenent tres, Iniciat II. Bé per treballar aquí.',
  'Aquí las cosas se miden bien o no se miden. No hay término medio.': 'Aquí les coses es mesuren bé o no es mesuren. No hi ha terme mig.',
  'Lo que yo te diga, cuando yo te lo diga. Pero aprender a medir. Eso siempre.': 'El que jo et digui, quan jo t\'ho digui. Però aprendre a mesurar. Això sempre.',
  'Veintidós años.': 'Vint-i-dos anys.',
  'Vuelve mañana. Tengo trabajo.': 'Torna demà. Tinc feina.',
  'Callejón estrecho entre galpones. Pared de ladrillo. La misma mano que en los Canales.': 'Carreró estret entre naus. Paret de maó. La mateixa mà que als Canales.',
  'Letra temblorosa: "La unidad es la medida de la obediencia."': 'Lletra tremolosa: «La unitat és la mesura de l\'obediència.»',
  'Hay más últimamente.': 'N\'hi ha més últimament.',
  'Camina.': 'Camina.',
  'Callejón cualquiera. De repente el mundo baja de volumen. Los pasos se apagan.': 'Un carreró qualsevol. De cop el món baixa de volum. Els passos s\'apaguen.',
  'Un Fragmento pequeño flota delante de ti. Muestra dos valores a la vez: 2/4 y 1/2.': 'Un Fragment petit flota davant teu. Mostra dos valors alhora: 2/4 i 1/2.',
  'Otro nuevo.': 'Un altre de nou.',
  '¿Vas a desfragmentarme, Aprendiz?': 'Em desfragmentaràs, Aprenent?',
  'Ah. Disculpa. Mejor así.': 'Ah. Perdona. Millor així.',
  'Eso es honesto. Mejor así.': 'Això és honest. Millor així.',
  'Vale. No hablas. Bien.': 'D\'acord. No parles. Bé.',
  'Eco gira despacio sobre sí mismo.': 'L\'Eco gira a poc a poc sobre si mateix.',
  'Tengo una pregunta.': 'Tinc una pregunta.',
  'Si tú y yo fuéramos el mismo pedazo de algo mayor, con nombres distintos, ¿seríamos la misma cosa?': 'Si tu i jo fóssim el mateix tros d\'una cosa més gran, amb noms diferents, seríem la mateixa cosa?',
  'Eco espera sin reloj.': 'L\'Eco espera sense rellotge.',
  'Entonces tú y yo ya somos.': 'Llavors tu i jo ja som.',
  'Entonces tú y yo todavía no somos.': 'Llavors tu i jo encara no som.',
  'Yo tampoco. Ven a verme otra vez cuando sepas.': 'Jo tampoc. Vine a veure\'m una altra vegada quan ho sàpigues.',
  'Otra vez será.': 'Una altra vegada serà.',
  'Eco se desvanece en partículas que suben. No bajan. El mundo vuelve a su volumen.': 'L\'Eco s\'esvaeix en partícules que pugen. No baixen. El món torna al seu volum.',
  'Muelle largo del Puerto Silencioso. Faro lejano parpadea. Mar negro.': 'Moll llarg del Port Silenciós. Far llunyà parpelleja. Mar negre.',
  'Hm.': 'Hm.',
  'Pausa muy larga. Ocho segundos contados.': 'Pausa molt llarga. Vuit segons comptats.',
  'Siéntate si quieres.': 'Seu si vols.',
  'Algo se mueve lejos en el mar. Se sumerge.': 'Alguna cosa es mou lluny al mar. Se submergeix.',
  'Oryn.': 'Oryn.',
  'Dices tu nombre.': 'Dius el teu nom.',
  'Aquí aprendes a multiplicar y a dividir.': 'Aquí aprens a multiplicar i a dividir.',
  'Fracciones. Fracciones entre ellas.': 'Fraccions. Fraccions entre elles.',
  'No es rápido.': 'No és ràpid.',
  'Te mira lo justo para incomodarte.': 'Et mira just el necessari per incomodar-te.',
  'Trabajamos de noche. Y el mar pide silencio. Algunos piensan que el mar escucha.': 'Treballem de nit. I el mar demana silenci. Alguns pensen que el mar escolta.',
  'Hm. Mucho.': 'Hm. Molt.',
  'Vale.': 'D\'acord.',
  'Vuelve mañana. Empezamos.': 'Torna demà. Comencem.',
  'Cafetería nocturna del Puerto. Ari ya ha pedido bebida para los dos.': 'Cafeteria nocturna del Port. L\'Ari ja ha demanat beguda per a tots dos.',
  '¡Eh!': 'Ei!',
  'No te esperaba aquí.': 'No t\'esperava aquí.',
  'Bueno, sí. Todo el mundo acaba pasando por el Puerto tarde o temprano.': 'Bé, sí. Tothom acaba passant pel Port tard o d\'hora.',
  'Oye. ¿Te puedo pedir una cosa?': 'Escolta. Et puc demanar una cosa?',
  'Llevo dos semanas viendo algo raro en el muelle 7. No voy a decir más aquí.': 'Fa dues setmanes que veig una cosa estranya al moll 7. No diré res més aquí.',
  'No es un Fragmento normal. Creo que es... otra cosa.': 'No és un Fragment normal. Crec que és... una altra cosa.',
  'Yo sola no voy. ¿Me acompañas mañana por la noche?': 'Sola no hi vaig. M\'acompanyes demà a la nit?',
  'Gracias, {nombre}. En serio. Aquí mismo mañana, a la misma hora.': 'Gràcies, {nombre}. De debò. Aquí mateix demà, a la mateixa hora.',
  'No. No sé cómo reaccionaría. Y además... quiero ver qué es primero.': 'No. No sé com reaccionaria. I a més... vull veure què és primer.',
  'Por eso te lo pido a ti.': 'Per això t\'ho demano a tu.',
  'Muelle 7. Un almacén viejo con la puerta entornada. Luz rojiza dentro.': 'Moll 7. Un magatzem vell amb la porta ajustada. Llum vermellosa dins.',
  'Un altar improvisado. Un Fragmento de valor 3/4 en una caja de cristal con filtros metálicos.': 'Un altar improvisat. Un Fragment de valor 3/4 en una caixa de vidre amb filtres metàl·lics.',
  'Alrededor: espejos antiguos, un reloj parado, una rosa disecada, un frasco con agua turbia.': 'Al voltant: miralls antics, un rellotge parat, una rosa dissecada, un flascó amb aigua tèrbola.',
  'Los objetos fuera del altar —silla, mesa— están mal proporcionados. Como si el espacio doblara.': 'Els objectes fora de l\'altar —cadira, taula— estan mal proporcionats. Com si l\'espai es doblegués.',
  '¿Ves?': 'Ho veus?',
  'Eso no es un Fragmento cualquiera.': 'Això no és un Fragment qualsevol.',
  'Alguien lo está usando.': 'Algú l\'està fent servir.',
  'Una puerta se cierra dentro del almacén. Pasos.': 'Una porta es tanca dins del magatzem. Passos.',
  'Vámonos.': 'Anem.',
  'Corréis. Atravesáis el muelle 7 en silencio. Al parar, Ari respira hondo.': 'Correu. Travesseu el moll 7 en silenci. En parar, l\'Ari respira fondo.',
  'Hay que contárselo.': 'Cal explicar-ho.',
  'A alguien. No sé a quién.': 'A algú. No sé a qui.',
  'Sora... no sé. Ella es de Tejados. Mejor a uno del distrito de aquí.': 'La Sora... no sé. Ella és de Teulades. Millor a un del districte d\'aquí.',
  'Oryn sabrá. Pero no sé si es la persona adecuada. Siempre me da la sensación de que sabe más cosas de las que dice.': 'L\'Oryn ho sabrà. Però no sé si és la persona adequada. Sempre tinc la sensació que sap més coses de les que diu.',
  'Sí. Ella sí. Naini reacciona. Los otros piensan demasiado antes.': 'Sí. Ella sí. La Naini reacciona. Els altres pensen massa abans.',
  'Despacho pequeño al fondo del Mercado. Una lámpara de mesa. Naini sin sonrisa por primera vez.': 'Despatx petit al fons del Mercado. Un llum de taula. La Naini sense somriure per primera vegada.',
  'Contádmelo. Paso a paso.': 'Expliqueu-m\'ho. Pas a pas.',
  'Escucha sin interrumpir. Toma notas. Hace un círculo en el papel.': 'Escolta sense interrompre. Pren notes. Fa un cercle al paper.',
  'Esto no es un Fragmento silvestre. Esto es una infraestructura.': 'Això no és un Fragment silvestre. Això és una infraestructura.',
  'Alguien está capturando Fragmentos y manteniéndolos vivos para que funcionen en un lugar concreto.': 'Algú està capturant Fragments i mantenint-los vius perquè funcionin en un lloc concret.',
  'Se llaman Coleccionistas. Algunos ricos que descubrieron hace décadas que un Fragmento grande, enjaulado, distorsiona el espacio a su alrededor.': 'Es diuen Col·leccionistes. Alguns rics que van descobrir fa dècades que un Fragment gran, engabiat, distorsiona l\'espai al seu voltant.',
  'Y si lo pones bien, distorsiona a tu favor.': 'I si el poses bé, distorsiona al teu favor.',
  'Contratos que firmas dentro te favorecen. Reuniones duran lo que te conviene.': 'Contractes que signes dins t\'afavoreixen. Reunions duren el que et convé.',
  'Gente que visita tu oficina olvida la mitad de lo que iba a decirte.': 'Gent que visita la teva oficina oblida la meitat del que t\'havia de dir.',
  'Es difícil de probar. Y es muy viejo.': 'És difícil de demostrar. I és molt vell.',
  'Ari, esto lo has hecho bien.': 'Ari, això ho has fet bé.',
  '{nombre}, tú también.': '{nombre}, tu també.',
  'Primera vez que un maestro os mira como colegas. No como alumnos.': 'Primera vegada que un mestre us mira com a col·legues. No com a alumnes.',
  'Lo voy a llevar al Cónclave. Es nivel Fraccionista Mayor.': 'Ho portaré al Conclave. És nivell Fraccionista Major.',
  'Primera vez que un maestro te da las gracias. Ari te mira de reojo. Tú también a ella.': 'Primera vegada que un mestre et dóna les gràcies. L\'Ari et mira de reüll. Tu també a ella.',
  'Vosotros dos no habéis estado nunca en ese muelle. ¿De acuerdo?': 'Vosaltres dos no heu estat mai en aquell moll. D\'acord?',
  'Bien. Hala. Id a descansar.': 'Bé. Au. Aneu a descansar.',
  'Azotea principal. Sora al fondo sin acercarse. Kai sentado contra un respiradero mirando el cielo.': 'Terrat principal. La Sora al fons sense acostar-se. El Kai assegut contra un respirador mirant el cel.',
  'Te está esperando.': 'T\'està esperant.',
  'Me enteré de lo del muelle 7.': 'Em vaig assabentar del moll 7.',
  'No vas a creerme, pero...': 'No em creuràs, però...',
  'Yo llevaba un mes sospechando algo así en la calle donde vive mi padre.': 'Jo feia un mes que sospitava una cosa així al carrer on viu el meu pare.',
  'Kai sin máscara. No es la primera vez que baja la guardia contigo pero sí es la más honda.': 'El Kai sense màscara. No és el primer cop que abaixa la guàrdia amb tu però sí el més profund.',
  'No tengo pruebas. Pero cuando la gente entra a cenar con mi padre, salen distintas.': 'No tinc proves. Però quan la gent entra a sopar amb el meu pare, surten diferents.',
  'No lo he hablado con nadie.': 'No ho he parlat amb ningú.',
  'Necesito ayuda.': 'Necessito ajuda.',
  'La oficina cerrada. La gente que sale confusa. Dos veces al mes. Mucha gente.': 'L\'oficina tancada. La gent que surt confusa. Dues vegades al mes. Molta gent.',
  'Porque ya no confío en los que llevo años conociendo. Y tú acabas de hacer algo que yo no sabía hacer.': 'Perquè ja no confio en els que fa anys que conec. I tu acabes de fer una cosa que jo no sabia fer.',
  'Gracias por no preguntar nada.': 'Gràcies per no preguntar res.',
  'Mañana te cuento más.': 'Demà t\'explico més.',
  'Has estado bien. En el duelo.': 'Has estat bé. Al duel.',
  'Sora murmura al fondo, casi para sí misma:': 'La Sora murmura al fons, gairebé per a ella mateixa:',
  'Barrio residencial entre Canales e Industria. Portal de una casa cualquiera. Un Fragmento Impropio de valor 9/5 flota a media altura.': 'Barri residencial entre Canales i Indústria. Portal d\'una casa qualsevol. Un Fragment Impropi de valor 9/5 flota a mitja alçada.',
  'Impropio.': 'Impropi.',
  'Si lo convertimos en mixto, es 1 y 4/5.': 'Si el convertim en mixt, és 1 i 4/5.',
  '¿Lo estabilizas tú o yo?': 'L\'estabilitzes tu o jo?',
  'Vale. Yo ataco.': 'D\'acord. Jo ataco.',
  'Vale. Tú atacas.': 'D\'acord. Tu ataques.',
  'Vale. Juntos.': 'D\'acord. Junts.',
  'El Fragmento se estabiliza. Kai, ya de compañero:': 'El Fragment s\'estabilitza. El Kai, ja com a company:',
  'Espera.': 'Espera.',
  'Ahora.': 'Ara.',
  'Tu turno.': 'El teu torn.',
  'El Fragmento se disuelve limpio. Kai guarda algo en el bolsillo. No dice qué.': 'El Fragment es dissol net. El Kai guarda una cosa a la butxaca. No diu què.',
  'Mañana te paso algo por escrito.': 'Demà et passo una cosa per escrit.',
  'De lo de mi padre.': 'Sobre el meu pare.',
  'Por si no te vuelvo a ver en un tiempo.': 'Per si no et torno a veure durant un temps.',
  'Observatorio antiguo al borde de un campo. Cielo estrellado. Dos lunas esta noche.': 'Observatori antic a la vora d\'un camp. Cel estrellat. Dues llunes aquesta nit.',
  'Ah, tú.': 'Ah, tu.',
  'Brina. Maestra de las Afueras. Y profesora, pero eso es otra cosa.': 'Brina. Mestra de les Afores. I professora, però això és una altra cosa.',
  'Déjame pensar.': 'Deixa\'m pensar.',
  'Tú eres el que hizo lo de Zafrán con Sora y acaba de descubrir algo en el Puerto con Ari y trabajó ayer con Kai.': 'Tu ets el que va fer allò de Zafrán amb la Sora i acaba de descobrir una cosa al Port amb l\'Ari i va treballar ahir amb el Kai.',
  'Meses resumidos en una frase.': 'Mesos resumits en una frase.',
  'Aquí trabajamos con datos. Probabilidades. Tendencias.': 'Aquí treballem amb dades. Probabilitats. Tendències.',
  'Te voy a enseñar una cosa que te va a parecer aburrida. No lo es.': 'Et mostraré una cosa que et semblarà avorrida. No ho és.',
  'Te pone una tabla delante. Fechas en una columna. Números que suben en la otra.': 'Et posa una taula al davant. Dates en una columna. Números que pugen a l\'altra.',
  '¿Qué ves?': 'Què veus?',
  'Bien. ¿Sabes qué miden?': 'Bé. Saps què mesuren?',
  'Te lo iba a contar igual.': 'T\'ho volia explicar igualment.',
  'Son Fragmentos. Fragmentos aparecidos en Azula cada mes.': 'Són Fragments. Fragments apareguts a Azula cada mes.',
  'En los últimos dos años han subido un 17% cada trimestre.': 'En els últims dos anys han pujat un 17% cada trimestre.',
  'Nadie se lo cuenta a los Fraccionistas nuevos. No quieren asustar.': 'Ningú no ho explica als Fraccionistes nous. No volen espantar.',
  'Pero tú ya eres Iniciado III. Tienes que saber.': 'Però tu ja ets Iniciat III. Has de saber-ho.',
  'Azula está peor cada año.': 'Azula està pitjor cada any.',
  'Y no sabemos por qué.': 'I no sabem per què.',
  'Mirador al borde de Afueras. Vista clara a la Montaña. La luna recorta su silueta.': 'Mirador a la vora d\'Afores. Vista clara a la Montaña. La lluna retalla la seva silueta.',
  'Todos acaban mirándola.': 'Tothom acaba mirant-la.',
  '¿Irune te ha hablado de ella?': 'L\'Irune t\'ha parlat d\'ella?',
  'Ahí arriba vive alguien que todavía cree que puede repararse.': 'Allà dalt viu algú que encara creu que es pot reparar.',
  'El Uno. Lo que se rompió.': 'L\'U. El que es va trencar.',
  'El Algebrista.': 'L\'Algebrista.',
  'Vale. Te lo cuento.': 'D\'acord. T\'ho explico.',
  'Hace décadas que nadie sube. Irune no sube.': 'Fa dècades que ningú no hi puja. L\'Irune no hi puja.',
  'Algunos dicen que ya no vive. Yo creo que sí.': 'Alguns diuen que ja no viu. Jo crec que sí.',
  'Algún día vas a querer subir.': 'Algun dia voldràs pujar-hi.',
  'No hoy. No este año. Pero algún día.': 'No avui. No aquest any. Però algun dia.',
  'Cuando te toque, alguien te ayudará a ir. Irune. Sora. Alguien.': 'Quan et toqui, algú t\'ajudarà a anar-hi. Irune. Sora. Algú.',
  'Sala de Irune. Chimenea encendida. Sora al fondo con un libro cerrado. Irune sirve té.': 'Sala de l\'Irune. Xemeneia encesa. La Sora al fons amb un llibre tancat. L\'Irune serveix te.',
  'Han pasado muchas cosas.': 'Han passat moltes coses.',
  'Zafrán. El muelle 7. Kai. Eco.': 'Zafrán. El moll 7. Kai. Eco.',
  'La última palabra con un tono distinto.': 'L\'última paraula amb un to diferent.',
  'Sí. Sé lo de Eco.': 'Sí. Sé el de l\'Eco.',
  'No te preocupes por él. De momento.': 'No et preocupis per ell. De moment.',
  'Has conocido a todos los maestros menos a Oryn bien. Eso te falta.': 'Has conegut tots els mestres menys l\'Oryn bé. Això et falta.',
  'Y cuando lo conozcas, estarás listo.': 'I quan el coneguis, estaràs llest.',
  'Iniciado III, pronto. Fraccionista, en unos meses.': 'Iniciat III, aviat. Fraccionista, d\'aquí a uns mesos.',
  'Mira a Sora un momento. Sora no se mueve.': 'Mira la Sora un moment. La Sora no es mou.',
  'Cuando seas Fraccionista, ya no hace falta que nadie vaya contigo a ningún sitio.': 'Quan siguis Fraccionista, ja no cal que ningú vagi amb tu enlloc.',
  'Entonces vas a tener que empezar a decidir tú qué hacer con lo que sabes.': 'Llavors hauràs de començar a decidir tu què fer amb el que saps.',
  'Es menos cómodo de lo que parece.': 'És menys còmode del que sembla.',
  'Sonrisa pequeña.': 'Somriure petit.',
  'Descansa. Vete con Sora.': 'Descansa. Vés amb la Sora.',
  'Azotea. Borde. Sora apoyada. Tú a su lado. Ninguno habla. Azula abajo, todos sus distritos, la Montaña al fondo.': 'Terrat. Vora. La Sora recolzada. Tu al seu costat. Cap dels dos no parla. Azula a sota, tots els seus districtes, la Montaña al fons.',
  'Muelle largo del Puerto. Más niebla que la última vez. Sin Ari.': 'Moll llarg del Port. Més Niebla que l\'última vegada. Sense l\'Ari.',
  'Hoy empezamos.': 'Avui comencem.',
  'Iniciado III. Sí.': 'Iniciat III. Sí.',
  'Aquí vas a aprender una cosa que parece magia. Multiplicar dos fracciones entre sí.': 'Aquí aprendràs una cosa que sembla màgia. Multiplicar dues fraccions entre si.',
  'Dos tercios por tres cuartos.': 'Dos terços per tres quarts.',
  'El resultado es más pequeño que los dos.': 'El resultat és més petit que els dos.',
  'Parece mentira. No lo es.': 'Sembla mentida. No ho és.',
  'Cobertizo al final del muelle. Un tablón viejo con cuerdas con nudos. Un dispositivo de entrenamiento casero.': 'Cobert al final del moll. Un tauló vell amb cordes amb nusos. Un dispositiu d\'entrenament casolà.',
  'Esto lo hice yo. Hace años.': 'Això ho vaig fer jo. Fa anys.',
  'Cuando multiplicas una fracción por otra, tomas una parte de una parte.': 'Quan multipliques una fracció per una altra, prens una part d\'una part.',
  'Si te quedas con la mitad de tres cuartos, ¿cuánto tienes?': 'Si et quedes amb la meitat de tres quarts, quant tens?',
  'No. La mitad de algo es menos.': 'No. La meitat d\'una cosa és menys.',
  'Tres octavos. Menos que un medio. Menos que tres cuartos. Pero es la mitad de ese tres cuartos.': 'Tres vuitens. Menys que un mig. Menys que tres quarts. Però és la meitat d\'aquells tres quarts.',
  'No. Estás cogiendo la mitad, pero de tres cuartos, no de un entero.': 'No. Estàs agafant la meitat, però de tres quarts, no d\'un sencer.',
  'Esto hay que verlo muchas veces para que no parezca raro.': 'Això s\'ha de veure moltes vegades perquè no sembli estrany.',
  'Madrugada. El cielo aclara muy despacio. Oryn mira el mar durante tres minutos reales. Tú estás ahí.': 'Matinada. El cel s\'aclareix molt a poc a poc. L\'Oryn mira el mar durant tres minuts reals. Tu hi ets.',
  '{nombre}. Una cosa.': '{nombre}. Una cosa.',
  'El agua recuerda.': 'L\'aigua recorda.',
  'Silencio de cuatro segundos. La frase respira.': 'Silenci de quatre segons. La frase respira.',
  'Esa es una de las dos veces en que te lo voy a decir.': 'Aquesta és una de les dues vegades en què t\'ho diré.',
  'Si alguna vez estás perdido, vuelve aquí. No te digo por qué.': 'Si algun dia estàs perdut, torna aquí. No et dic per què.',
  'Solo vuelve.': 'Només torna.',
  'Mañana más. Descansa.': 'Demà més. Descansa.',
  'Abre la bolsa impermeable que nunca abre delante de nadie. Saca una concha plana pulida con un agujero natural y un hilo fino.': 'Obre la bossa impermeable que mai no obre davant de ningú. Treu una conquilla plana polida amb un forat natural i un fil prim.',
  'No vale nada. Pero la llevo mucho tiempo.': 'No val res. Però fa molt temps que la porto.',
  'Ahora la llevas tú.': 'Ara la portes tu.',
  'Cierra la bolsa. Entra al cobertizo. Cierra la puerta.': 'Tanca la bossa. Entra al cobert. Tanca la porta.',
  'Muro exterior al borde de Afueras. La misma mano que las dos anteriores.': 'Mur exterior a la vora d\'Afores. La mateixa mà que les dues anteriors.',
  'Frase nueva: "En la parte está la libertad."': 'Frase nova: "A la part hi ha la llibertat."',
  'Debajo, otra pintura más reciente, distinta, tachando la primera: "La parte sola no libra a nadie."': 'A sota, una altra pintura més recent, diferent, ratllant la primera: "La part sola no allibera ningú."',
  'Las dos frases coexisten. Alguien ha respondido.': 'Les dues frases coexisteixen. Algú ha respost.',
  'Un callejón parecido al de la primera vez. El mundo baja de volumen otra vez.': 'Un carreró semblant al de la primera vegada. El món baixa de volum una altra vegada.',
  'Pero nada aparece.': 'Però no apareix res.',
  'Silencio. Quince segundos. Te quedas quieto.': 'Silenci. Quinze segons. Et quedes quiet.',
  'El sonido vuelve. Sin explicación. Sientes que Eco estuvo a punto.': 'El so torna. Sense explicació. Sents que l\'Eco hi era a punt.',
  'Sala de Irune. Un plato de pastas pequeñas — nunca las había sacado antes. Dos tazas de té.': 'Sala de l\'Irune. Un plat de pastes petites — mai no les havia tret abans. Dues tasses de te.',
  'Te he llamado porque ha llegado el momento.': 'T\'he cridat perquè ha arribat el moment.',
  'Estás listo para la Prueba.': 'Estàs llest per a la Prova.',
  'No significa que sepas todo lo que tienes que saber. Significa que ya puedes demostrar lo que sabes.': 'No vol dir que sàpigues tot el que has de saber. Vol dir que ja pots demostrar el que saps.',
  'La diferencia es fina. Es real.': 'La diferència és fina. És real.',
  'Puedes decir que no. Puedes esperar unos meses. No te voy a presionar.': 'Pots dir que no. Pots esperar uns mesos. No et pressionaré.',
  'Pero si dices que sí, te explico las tres formas.': 'Però si dius que sí, t\'explico les tres formes.',
  'Bien. Escucha.': 'Bé. Escolta.',
  'Siéntate y te las explico.': 'Seu i te les explico.',
  'Tres Pruebas. Tú eliges una.': 'Tres Proves. Tu en tries una.',
  'Primera. Prueba de Fuego. Combate contra un Fragmento representativo de tu rango. Sin ayudas, sin Sora. Tú solo.': 'Primera. Prova de Foc. Combat contra un Fragment representatiu del teu rang. Sense ajudes, sense Sora. Tu sol.',
  'Es la más rápida. Tres minutos, cuatro. Intensa.': 'És la més ràpida. Tres minuts, quatre. Intensa.',
  'Para los que tienen confianza en su cuerpo.': 'Per als que tenen confiança en el seu cos.',
  'Segunda. Prueba de Sendero. Serie larga de Fragmentos, todos los tipos, con margen de error limitado. Mide tu fluidez.': 'Segona. Prova de Camí. Sèrie llarga de Fragments, tots els tipus, amb marge d\'error limitat. Mesura la teva fluïdesa.',
  'Es la más lenta. Veinte minutos. Meditativa.': 'És la més lenta. Vint minuts. Meditativa.',
  'Para los que tienen paciencia.': 'Per als que tenen paciència.',
  'Tercera. Prueba de Espejo.': 'Tercera. Prova de Mirall.',
  'Tienes que enseñar a alguien más joven que tú. Un Fraccionista que está donde tú estabas hace un año.': 'Has d\'ensenyar a algú més jove que tu. Un Fraccionista que és on tu eres fa un any.',
  'Te enfrentas a sus fallos. Le ayudas a resolverlos. Le haces preguntas, no le das respuestas.': 'T\'enfrontes als seus errors. L\'ajudes a resoldre\'ls. Li fas preguntes, no li dones respostes.',
  'Mide si entiendes lo que has aprendido. Si puedes explicarlo a otro.': 'Mesura si entens el que has après. Si ho pots explicar a un altre.',
  'Es la más difícil. Y la más importante, para muchos.': 'És la més difícil. I la més important, per a molts.',
  'Las tres valen lo mismo. Ninguna es superior a las otras. Elige.': 'Les tres valen el mateix. Cap no és superior a les altres. Tria.',
  'Bien. Mañana. Aquí. Después de cenar.': 'Bé. Demà. Aquí. Després de sopar.',
  'Azotea. Sora de pie con los brazos cruzados. Te estaba esperando.': 'Terrat. La Sora dempeus amb els braços creuats. T\'estava esperant.',
  '¿Cuál?': 'Quina?',
  'Dices: Fuego.': 'Dius: Foc.',
  'Clásica. Bien.': 'Clàssica. Bé.',
  'Solo una cosa. No vayas rápido. No es una carrera. La velocidad se entiende mal.': 'Només una cosa. No vagis ràpid. No és una cursa. La velocitat s\'entén malament.',
  'Respira en los cambios. Descomponer es también parar.': 'Respira en els canvis. Descompondre també és aturar-se.',
  'Suerte, {nombre}.': 'Sort, {nombre}.',
  'Cenamos. Luego entras.': 'Sopem. Després entres.',
  'Dices: Sendero.': 'Dius: Sender.',
  'Paciente. Bien.': 'Pacient. Bé.',
  'Es la que hice yo.': 'És la que vaig fer jo.',
  'Si te cansas a mitad, no te pares del todo. Cambia de ritmo. Descansa mientras sigues.': 'Si et canses a mitges, no t\'aturis del tot. Canvia de ritme. Descansa mentre continues.',
  'Dices: Espejo. Sora se queda callada dos segundos.': 'Dius: Mirall. Sora es queda callada dos segons.',
  'Esa es la más personal.': 'Aquesta és la més personal.',
  'Ten cuidado con lo que le dices al otro. A veces se te escapan cosas que no sabías que pensabas.': 'Vés amb compte amb el que dius a l\'altre. De vegades se t\'escapen coses que no sabies que pensaves.',
  'Y a veces... el otro se parece a alguien que no esperas.': 'I de vegades... l\'altre s\'assembla a algú que no esperes.',
  'Silencio. Sora nunca había sido tan explícita. No te mira directo.': 'Silenci. Sora mai no havia estat tan explícita. No et mira directament.',
  'Tengo que hacer un encargo. Te alcanzo al final.': 'He de fer un encàrrec. T\'agafo al final.',
  'Azotea. Seis maestros. Sora. Kai. Ari. Ninguno habla durante el combate. Vorax se retira hacia arriba como Zafrán.': 'Terrat. Sis mestres. Sora. Kai. Ari. Cap parla durant el combat. Vorax es retira cap amunt com Zafrán.',
  'Prueba de Sendero.': 'Prova de Sender.',
  'Esta noche vas a recorrer la ciudad. Cuatro distritos. Una prueba en cada uno.': 'Aquesta nit recorreràs la ciutat. Quatre districtes. Una prova a cadascun.',
  'En cada distrito te espera un Fragmento distinto, diseñado por el maestro correspondiente.': 'A cada districte t\'espera un Fragment diferent, dissenyat pel mestre corresponent.',
  'Nadie te va a acompañar. Nadie te va a ayudar.': 'Ningú t\'acompanyarà. Ningú t\'ajudarà.',
  'Empiezas en los Canales.': 'Comences als Canals.',
  'Canales. Niebla baja. Un Fragmento Espejo 5/10 esperando. Lo emparejas con 1/2. Silencio.': 'Canals. Boira baixa. Un Fragment Mirall 5/10 esperant. L\'emparelles amb 1/2. Silenci.',
  'Industria. Luz gris. Un Fragmento con unidades que no cuadran: 1,2 kg más 800 g. Un punto dos kilos.': 'Indústria. Llum grisa. Un Fragment amb unitats que no quadren: 1,2 kg més 800 g. U coma dos quilos.',
  'Mercado. Puestos cerrando. Un Fragmento con 40 manzanas y una pregunta: el 25% son rojas. Diez rojas.': 'Mercat. Parades tancant. Un Fragment amb 40 pomes i una pregunta: el 25% són vermelles. Deu vermelles.',
  'Afueras. Observatorio. Un Fragmento con una tendencia: tres meses subiendo 5. Lo que viene ya lo sabes.': 'Afores. Observatori. Un Fragment amb una tendència: tres mesos pujant 5. El que ve ja ho saps.',
  'Subes al Edificio de los Tejados antes del amanecer. Irune en la puerta.': 'Puges a l\'Edifici dels Terrats abans de l\'alba. Irune a la porta.',
  'Sala de Irune. Cerrada. Luz tenue. Dos sillas frente a frente. Irune sale. Niko sentado enfrente.': 'Sala de l\'Irune. Tancada. Llum tènue. Dues cadires l\'una davant de l\'altra. Irune surt. Niko assegut al davant.',
  'Pelo que te recuerda a alguien. Un gesto que no sabes por qué reconoces.': 'Cabells que et recorden algú. Un gest que no saps per què reconeixes.',
  'Tengo que aprender contigo.': 'He d\'aprendre amb tu.',
  'Irune me ha dicho que me vas a ayudar.': 'Irune m\'ha dit que m\'ajudaràs.',
  'Ejercicio 1: 2/3 + 1/5 = ? Niko ha puesto 3/8 (sumando numeradores y denominadores).': 'Exercici 1: 2/3 + 1/5 = ? Niko ha posat 3/8 (sumant numeradors i denominadors).',
  'No entiendo por qué está mal.': 'No entenc per què està malament.',
  'Vale, gracias.': 'D\'acord, gràcies.',
  'Más. Porque un tercio ya es casi medio. ¡Ah!': 'Més. Perquè un terç ja és gairebé mig. Ah!',
  'No. ¡Ah!': 'No. Ah!',
  'Niko calcula por su cuenta. Se pasa la mano por el pelo hacia atrás dos veces.': 'Niko calcula pel seu compte. Es passa la mà pels cabells cap enrere dues vegades.',
  '13/15. ¿Así está bien?': '13/15. Així està bé?',
  'Ejercicio 2: 35% de 80 = ?': 'Exercici 2: 35% de 80 = ?',
  'Sé que es algo así como 30. Pero no sé cómo pensarlo.': 'Sé que és una cosa com 30. Però no sé com pensar-ho.',
  'Vale. 28.': 'D\'acord. 28.',
  '24. Y 5% son 4. ¡28!': '24. I 5% són 4. 28!',
  'Se pasa la mano por el pelo otra vez. Dos veces. Como Sora cuando se concentra.': 'Es passa la mà pels cabells una altra vegada. Dues vegades. Com Sora quan es concentra.',
  'Irune me dijo que si alguien te explicaba esto bien, lo ibas a recordar siempre.': 'Irune em va dir que si algú t\'explicava això bé, ho recordaries sempre.',
  'Tú me lo explicaste bien.': 'Tu m\'ho vas explicar bé.',
  'Irune entra.': 'Irune entra.',
  'Se acabó.': 'S\'ha acabat.',
  'Niko se va por una puerta que no habías visto. "Hasta mañana."': 'Niko se\'n va per una porta que no havies vist. "Fins demà."',
  'Sora te espera fuera.': 'Sora t\'espera fora.',
  'Azotea, amanecer empezando. Todos los maestros en semicírculo. Sora entre ellos pero un paso atrás. Kai y Ari junto a la escalera.': 'Terrat, alba començant. Tots els mestres en semicercle. Sora entre ells però un pas enrere. Kai i Ari al costat de l\'escala.',
  'Repite conmigo.': 'Repeteix amb mi.',
  'Prometo buscar el Uno que fue.': 'Prometo buscar l\'U que va ser.',
  'Repites.': 'Repeteixes.',
  'Prometo proteger el mundo que queda.': 'Prometo protegir el món que queda.',
  'Prometo no pretender nunca que sé más de lo que sé.': 'Prometo no pretendre mai que sé més del que sé.',
  'Saca una marca nueva — más grande, plata clara, símbolo de la orden en relieve. Te cambia la del cuello.': 'Treu una marca nova — més gran, plata clara, símbol de l\'ordre en relleu. Et canvia la del coll.',
  'Bienvenido, Fraccionista.': 'Benvingut, Fraccionista.',
  'Hace mucho que no ponía una de estas.': 'Fa molt que no en posava una d\'aquestes.',
  'Cada maestro da un paso adelante y dice su palabra antigua:': 'Cada mestre fa un pas endavant i diu la seva paraula antiga:',
  'Cinco "bien" con cinco voces distintas. Hermoso sin necesitar más.': 'Cinc "bé" amb cinc veus diferents. Bonic sense necessitar més.',
  'Sora da un paso adelante. Frente a ti. Silencio de tres segundos.': 'Sora fa un pas endavant. Davant teu. Silenci de tres segons.',
  'En serio. Gracias.': 'De debò. Gràcies.',
  'La palabra dicha dos veces. Enorme para Sora. Se aparta al borde del semicírculo.': 'La paraula dita dues vegades. Enorme per a Sora. S\'aparta a la vora del semicercle.',
  'Por hoy está.': 'Per avui està.',
  'Esquina apartada de la azotea. Dos vasos pequeños humeantes.': 'Cantonada apartada del terrat. Dos gots petits fumejants.',
  'Bébelo caliente.': 'Beu-t\'ho calent.',
  'Te ha tocado llevarme en este año.': 'T\'ha tocat portar-me aquest any.',
  'Has sido muy buen aprendiz.': 'Has estat molt bon aprenent.',
  'Ya no eres mi aprendiz. Ahora eres mi colega.': 'Ja no ets el meu aprenent. Ara ets el meu col·lega.',
  'Si alguna vez quieres bajar a los Canales solo para hablar, me avisas.': 'Si algun dia vols baixar als Canals només per parlar, m\'avises.',
  'Yo estaré.': 'Jo hi seré.',
  'Saca una pequeña marca vieja, muy desteñida.': 'Treu una petita marca vella, molt desteyida.',
  'Era la primera marca de Fraccionista que me pusieron.': 'Era la primera marca de Fraccionista que em van posar.',
  'Ya tengo otras con más filetes azules.': 'Ja en tinc d\'altres amb més filets blaus.',
  'Pero esta es la primera.': 'Però aquesta és la primera.',
  'Cuida la tuya, {nombre}.': 'Cuida la teva, {nombre}.',
  'Otra parte de la azotea. Kai apoyado en un respiradero, solo.': 'Una altra part del terrat. Kai recolzat en un respirador, sol.',
  'Fraccionista.': 'Fraccionista.',
  'Va delante, mira.': 'Va al davant, mira.',
  'Se señala a sí mismo. Sigue siendo Iniciado III. Tú ahora un rango por encima.': 'Es senyala a si mateix. Continua sent Iniciat III. Tu ara un rang per sobre.',
  'Yo lo soy en unos meses. Si no me distraigo.': 'Jo ho seré en uns mesos. Si no em distrec.',
  'Lo de mi padre sigue en pie. Cuando me recuperes como colega, hablamos.': 'El del meu pare continua en peu. Quan em recuperis com a col·lega, en parlem.',
  'Enhorabuena, {nombre}.': 'Enhorabona, {nombre}.',
  'Asiente una sola vez. Forma máxima de reconocimiento. Primera vez que dice "enhorabuena".': 'Assenteix una sola vegada. Forma màxima de reconeixement. Primera vegada que diu "enhorabona".',
  'Todos se han ido. Sora sentada en el borde norte, piernas colgando. Alba avanzada. La ciudad con luz limpia por primera vez. Distritos distinguibles. Montaña al fondo.': 'Tots se n\'han anat. Sora asseguda a la vora nord, cames penjant. Alba avançada. La ciutat amb llum neta per primera vegada. Districtes distingibles. Montaña al fons.',
  'Bueno.': 'Bé.',
  'Lo has hecho.': 'Ho has fet.',
  'Te voy a decir una cosa y luego no la digo más.': 'Et diré una cosa i després no la diré més.',
  'Yo llegué a Azula hace dos años. Sola.': 'Jo vaig arribar a Azula fa dos anys. Sola.',
  'Mi ciudad se llamaba Kir. Estaba al norte, al borde del mar.': 'La meva ciutat es deia Kir. Era al nord, a la vora del mar.',
  'La palabra KIR queda un instante en el aire. Recuérdala.': 'La paraula KIR queda un instant a l\'aire. Recorda-la.',
  'La perdimos.': 'La vam perdre.',
  'Yo tenía once años cuando pasó.': 'Jo tenia onze anys quan va passar.',
  'Silencio muy largo.': 'Silenci molt llarg.',
  'No entré aquí porque quisiera salvar el mundo.': 'No vaig entrar aquí perquè volgués salvar el món.',
  'Entré porque no quería que pasara otra vez.': 'Vaig entrar perquè no volia que passés una altra vegada.',
  'Eso es todo. Pregúntame otro día si quieres más.': 'Això és tot. Pregunta\'m un altre dia si en vols més.',
  'No creo que lo hagas.': 'No crec que ho facis.',
  'Media sonrisa.': 'Mig somriure.',
  'Tú no preguntas. Me gustó desde el principio.': 'Tu no preguntes. Em va agradar des del començament.',
  'Gesto hacia la Montaña.': 'Gest cap a la Montaña.',
  'Brina te habló de ella.': 'Brina te\'n va parlar.',
  'Ahí sube el que sea Fraccionista Mayor.': 'Allà puja qui sigui Fraccionista Major.',
  'Yo tardaré. Tú tardarás más aún, porque empezaste más tarde.': 'Jo trigaré. Tu trigaràs encara més, perquè vas començar més tard.',
  'Pero cuando llegue el momento, subimos juntos.': 'Però quan arribi el moment, pugem junts.',
  'Te lo prometo.': 'T\'ho prometo.',
  'No te prometo que la pelea valga la pena.': 'No et prometo que la baralla valgui la pena.',
  'Te prometo que te acompaño.': 'Et prometo que t\'acompanyo.',
  'Saca la brújula vieja. Te cierra los dedos sobre ella.': 'Treu la brúixola vella. Et tanca els dits al damunt.',
  'Quédatela.': 'Queda-te-la.',
  'Ya no la necesito yo.': 'Jo ja no la necessito.',
  'Amanecer completo. La Montaña iluminada con nitidez por primera vez. Rocas. Laderas. Cumbre nevada. Un sendero tenue en un flanco.': 'Alba completa. La Montaña il·luminada amb nitidesa per primera vegada. Roques. Vessants. Cim nevat. Un sender tènue en un flanc.',
  'Tú y Sora como siluetas pequeñas de espaldas. Viento. Amanecer.': 'Tu i Sora com a siluetes petites d\'esquena. Vent. Alba.',
  'Silencio. Fundido a blanco.': 'Silenci. Fos a blanc.',
  'FIN DEL ARCO IV. EL ASCENSO.': 'FI DE L\'ARC IV. L\'ASCENS.',
  'URO UNO ROTO': 'URO UN TRENCAT',
  'FIN DEL MVP.': 'FI DEL MVP.',
  'HASTA ENTONCES': 'FINS LLAVORS',
  'Noche despejada. Las dos lunas bajas, claras.': 'Nit clara. Les dues llunes baixes, nítides.',
  'Arriba. Abajo. Arriba. Abajo.': 'Amunt. Avall. Amunt. Avall.',
  'Céntrate.': 'Concentra\'t.',
  'Cuando se parte un Fragmento, no pienses en las partes.': 'Quan es parteix un Fragment, no pensis en les parts.',
  'Piensa en el tamaño de cada parte.': 'Pensa en la mida de cada part.',
  'Las partes pequeñas son más fáciles. Siempre.': 'Les parts petites són més fàcils. Sempre.',
  'Niebla baja. No se ven las lunas. La ciudad se oye pero no se ve.': 'Boira baixa. No es veuen les llunes. La ciutat se sent però no es veu.',
  'Días así, hay más Fragmentos.': 'Dies així, hi ha més Fragments.',
  'No sé por qué. Irune dice que la niebla les gusta.': 'No sé per què. Irune diu que la boira els agrada.',
  'Mantente cerca.': 'Queda\'t a prop.',
  'La sesión es más corta esta noche. Sora lo nota.': 'La sessió és més curta aquesta nit. Sora ho nota.',
  'Hoy no más. Mañana.': 'Avui no més. Demà.',
  'Lluvia ligera. Las tejas mojadas brillan bajo las farolas.': 'Pluja lleugera. Les teules mullades brillen sota els fanals.',
  'Si te caes, te caes. No pasa nada.': 'Si caus, caus. No passa res.',
  'Cae mejor.': 'Cau millor.',
  'Risa corta. Solo un instante — se la traga enseguida.': 'Riure curt. Només un instant — se l\'empassa de seguida.',
  'Cielo muy limpio. La Montaña se ve entera al horizonte.': 'Cel molt net. La Montaña es veu sencera a l\'horitzó.',
  'Sora la mira sin decir nada un rato largo.': 'Sora la mira sense dir res una bona estona.',
  'Un Algebrista. O eso dicen. Fragmentos. Vamos.': 'Un Algebrista. O això diuen. Fragments. Som-hi.',
  'Porque no quiero llegar tarde.': 'Perquè no vull arribar tard.',
  'Otro día.': 'Un altre dia.',
  'Hablas poco. Me gusta.': 'Parles poc. M\'agrada.',
  'La sesión termina antes de lo previsto. Sora asiente una vez.': 'La sessió s\'acaba abans del previst. Sora assenteix una vegada.',
  'Aprendes rápido.': 'Aprens ràpid.',
  'No te lo creas mucho.': 'No t\'ho creguis gaire.',
  'Baja por la escalera sin girarse.': 'Baixa per l\'escala sense girar-se.',
  'Hasta mañana.': 'Fins demà.',
  'Eh. Eres tú, ¿no?': 'Eh. Ets tu, oi?',
  'Me han dicho que tienes buen ojo.': 'M\'han dit que tens bon ull.',
  'Vamos a ver si es verdad.': 'Anem a veure si és veritat.',
  'Mira ahí abajo. En el callejón.': 'Mira allà baix. Al carreró.',
  'Ese se come el cartel de neón. Pártelo en dos.': 'Aquest es menja el cartell de neó. Parteix-lo en dos.',
  'Otro. Este va a por el reloj del kiosco. En tres.': 'Un altre. Aquest va a pel rellotge del quiosc. En tres.',
  'Fácil. El letrero de la panadería. En dos.': 'Fàcil. El rètol de la fleca. En dos.',
  'Ese se ha tragado media ventana. En cuatro iguales.': 'Aquest s\'ha empassat mitja finestra. En quatre iguals.',
  'Baja al metro ese. Tres trenes dependen de cómo cortes esto.': 'Baixa al metro aquest. Tres trens depenen de com tallis això.',
  'Este es rápido. Se come lo que la gente intenta decir. En cinco.': 'Aquest és ràpid. Es menja el que la gent intenta dir. En cinc.',
  'Cuatro escalones, cuatro cortes. Mira el centro.': 'Quatre graons, quatre talls. Mira el centre.',
  'Banderines. Cuélgalo tú otra vez. En tres.': 'Banderoles. Penja-ho tu una altra vegada. En tres.',
  'Quíntuple. Si no lo pillas, toda la calle va a retraso.': 'Quíntuple. Si no l\'enganxes, tot el carrer va amb retard.',
  'Último de esta noche. El espejo de la moto. En cuatro.': 'Últim d\'aquesta nit. El mirall de la moto. En quatre.',
  'Ya está por hoy.': 'Ja està per avui.',
  'Diez Fragmentos. No se te da mal.': 'Deu Fragments. No se\'t dona malament.',
  'Vete a dormir. Mañana los cazamos más gordos.': 'Vés a dormir. Demà els cacem més grossos.',
  'Anda, has vuelto.': 'Vaja, has tornat.',
  'Pensaba que te habías asustado.': 'Em pensava que t\'havies espantat.',
  'Hoy hay más. Venga.': 'Avui n\'hi ha més. Vinga.',
  'Bici abandonada al fondo. Tres pedales quedan visibles.': 'Bici abandonada al fons. Tres pedals queden visibles.',
  'La sombra del farol. En dos. Sin pensarlo mucho.': 'L\'ombra del fanal. En dos. Sense pensar-ho gaire.',
  'Radio del vecino del cuarto. Cinco emisoras. No deja oír nada.': 'Ràdio del veí del quart. Cinc emissores. No deixa sentir res.',
  'Cartel roto. Cuatro esquinas que no cuadran.': 'Cartell trencat. Quatre cantonades que no quadren.',
  'Semáforo. Tres colores. Se está comiendo el amarillo.': 'Semàfor. Tres colors. Es menja el groc.',
  'Molinillo en una ventana. Cinco aspas. Se ha parado por su culpa.': 'Molinet en una finestra. Cinc aspes. S\'ha aturat per culpa seva.',
  'Alcantarilla cuadrada. Cuatro lados. Uno va a faltar.': 'Claveguera quadrada. Quatre costats. Un en faltarà.',
  'Paloma durmiendo en una cornisa. En dos. Sin hacer ruido.': 'Colom dormint en una cornisa. En dos. Sense fer soroll.',
  'Música de un bar. Tres estrofas. Se comen alternas.': 'Música d\'un bar. Tres estrofes. Se les mengen alternes.',
  'Último. Este se come el tiempo antes de que salga el sol. Cinco.': 'Últim. Aquest es menja el temps abans que surti el sol. Cinc.',
  'Mira. Ya es casi de día.': 'Mira. Ja és gairebé de dia.',
  'Veinte Fragmentos en dos noches.': 'Vint Fragments en dues nits.',
  'No está mal.': 'No està malament.',
  'Vete a descansar.': 'Vés a descansar.',
  'Vaya. Ya eres habitual.': 'Vaja. Ja ets habitual.',
  'Hoy no valen los fáciles.': 'Avui no valen els fàcils.',
  'Algunos Fragmentos son a trozos. No los partes de una vez.': 'Alguns Fragments són a trossos. No els parteixes d\'una vegada.',
  'Uno a uno. Como quien desata un nudo.': 'Un a un. Com qui desfà un nus.',
  'Entramos suaves. Un zapato olvidado. En tres.': 'Entrem suaus. Una sabata oblidada. En tres.',
  'Ese ha mordido dos tercios. Son dos trozos de un tercio. Uno, y después otro.': 'Aquest ha mossegat dos terços. Són dos trossos d\'un terç. Un, i després un altre.',
  'Grafiti nuevo. Cuatro colores. Córtalo igual.': 'Grafit nou. Quatre colors. Talla\'l igual.',
  'Tres cuartos de la ventana del ático. Tres veces en cuatro.': 'Tres quarts de la finestra de les golfes. Tres vegades en quatre.',
  'Guitarra en el balcón. Cinco cuerdas. Suave.': 'Guitarra al balcó. Cinc cordes. Suau.',
  'Marquesina rota. Dos quintos. Dos pasadas en cinco.': 'Marquesina trencada. Dos cinquens. Dues passades en cinc.',
  'Mosaico de la plaza. Cinco de seis baldosas. Concentra.': 'Mosaic de la plaça. Cinc de sis rajoles. Concentra.',
  'El eco del último tren. En dos. Rápido antes de que pare.': 'L\'eco de l\'últim tren. En dos. Ràpid abans que pari.',
  'Ironía: Fragmento devora tres de cinco carteles. Tres trozos en cinco.': 'Ironia: Fragment devora tres de cinc cartells. Tres trossos en cinc.',
  'Este se ha comido casi el reloj entero. Siete de ocho. Paciencia.': 'Aquest s\'ha menjat gairebé el rellotge sencer. Set de vuit. Paciència.',
  'Bien. Los compuestos no son un muro.': 'Bé. Els compostos no són un mur.',
  'Son una cadena. Un eslabón cada vez.': 'Són una cadena. Una baula cada vegada.',
  'Mañana te presento a alguien.': 'Demà et presento algú.',
  'Vete a dormir.': 'Vés a dormir.',
  'Venga, sin calentar.': 'Vinga, sense escalfar.',
  'Hoy vas con los ojos abiertos.': 'Avui vas amb els ulls oberts.',
  'Y te aguantas lo que toque.': 'I t\'aguantes el que toqui.',
  'Plaza central. Cuatro farolas. Una a una.': 'Plaça central. Quatre fanals. Un a un.',
  'Escaparate de la tintorería. Dos trozos en cinco.': 'Aparador de la tintoreria. Dos trossos en cinc.',
  'Vecinas discutiendo en el patio. En tres. Que vuelvan a oírse.': 'Veïnes discutint al pati. En tres. Que se sentin de nou.',
  'Ni me mires. El de Kai. Cinco trozos en siete. Tú solo.': 'Ni em miris. El de Kai. Cinc trossos en set. Tu sol.',
  'Respira. Batería de un bar. En cinco. Coge su compás.': 'Respira. Bateria d\'un bar. En cinc. Agafa el seu compàs.',
  'Mural pintado hace un mes. Tres cuartos. No dejes que se borre.': 'Mural pintat fa un mes. Tres quarts. No deixis que s\'esborri.',
  'Conversación a medias. En dos. Que las dos partes se oigan.': 'Conversa a mitges. En dos. Que les dues parts se sentin.',
  'El tejado de este edificio. Casi entero. Cuatro en cinco.': 'El terrat d\'aquest edifici. Gairebé sencer. Quatre en cinc.',
  'Este se come los días. Tres de siete. Te los devuelves.': 'Aquest es menja els dies. Tres de set. Te\'ls retornes.',
  'Último. Cinco octavos de la calle entera. Con calma.': 'Últim. Cinc vuitens del carrer sencer. Amb calma.',
  'Vaya, vaya.': 'Vaja, vaja.',
  'Tú eres el que se rumorea.': 'Tu ets el que es rumoreja.',
  'Me han dicho que vas por el tercero en los tejados.': 'M\'han dit que vas pel tercer als terrats.',
  'Yo iba por el séptimo a tu edad.': 'Jo anava pel setè a la teva edat.',
  'Toma. Este se me ha cruzado. Todo tuyo.': 'Té. Aquest se m\'ha creuat. Tot teu.',
  'A ver cómo sales.': 'A veure com te\'n surts.',
  'Déjalo. Ya se irá.': 'Deixa\'l. Ja se n\'anirà.',
  'Y no le contestes. Le pone.': 'I no li contestis. L\'engresca.',
  'Ha estado bien. El de Kai lo has llevado.': 'Ha estat bé. El de Kai l\'has portat.',
  'No se lo digas. Ya lo sabe.': 'No li ho diguis. Ja ho sap.',
  'Vete a dormir. Mañana otra vez.': 'Vés a dormir. Demà una altra vegada.',
  // Línies ambient de Sora durant la cacera (pantalla_caza)
  'Ya volverá otro.': 'Ja en tornarà un altre.',
  'Bien. El primero ya es tuyo.': 'Bé. El primer ja és teu.',
  'Cinco. Te estás haciendo a esto.': 'Cinc. T\'hi estàs fent.',
  'Diez en una noche. Mira el barrio.': 'Deu en una nit. Mira el barri.',
  'Veinte. A ver si te atreves con los primos.':
      'Vint. A veure si t\'atreveixes amb els primers.',
  'Otro menos.': 'Un altre menys.',
