  'Bien visto.': 'Ben vist.',
  'Sigue.': 'Segueix.',
  'Se te ha ido. No pasa nada.': 'Se t\'ha escapat. No passa res.',
  'Se han escapado varios. Atento.': 'Se n\'han escapat uns quants. Atent.',
