  'Niebla baja en el patio. Un Fragmento pequeño, casi del tamaño de una manzana, flota a media altura.': 'Boira baixa al pati. Un Fragment petit, quasi de la mida d\'una poma, sura a mitja alçada.',
  'No huye. No se acerca. Pulsa despacio, como si respirara.': 'No fuig. No s\'acosta. Polsa a poc a poc, com si respirés.',
  'Lo que tiene el desajuste. No parece mucho.': 'El que té el desajust. No sembla gaire.',
  'No lo tocas. Pasas de largo. El Fragmento sigue donde estaba.': 'No el toques. Passes de llarg. El Fragment segueix on era.',
  'Sala de mezclas. Una máquina marca 0,25 l. Vadic acerca un medidor externo y lee 0,3 l.': 'Sala de mescles. Una màquina marca 0,25 L. La Vadic acosta un mesurador extern i llegeix 0,3 L.',
  '0,3. Correcto. La máquina miente por 0,05.': '0,3. Correcte. La màquina menteix per 0,05.',
  'No. Un metro es cien centímetros. Pero estamos midiendo área. Piénsalo otra vez.': 'No. Un metre és cent centímetres. Però estem mesurant àrea. Pensa-ho una altra vegada.',
  'Vadic escucha. Asiente.': 'La Vadic escolta. Assenteix.',
  'Mesa de Vadic. Una libreta con cifras: 3 kg, 0,4 l, 250 g, 1,2 kg, 750 ml.': 'Taula de la Vadic. Una llibreta amb xifres: 3 kg, 0,4 L, 250 g, 1,2 kg, 750 mL.',
  'Multiplícalo por mil mezclas al día.': 'Multiplica-ho per mil mescles al dia.',
  'Asiente una vez sin girarse. Sigue mirando.': 'Assenteix un cop sense girar-se. Segueix mirant.',
  '«Sé otras cosas. Vas aprendiendo las tuyas.»': '«Sé altres coses. Vas aprenent les teves.»',
  '«No te creas que sé más que tú.»': '«No creguis que sé més que tu.»',
  'Calle estrecha entre los Tejados y los Canales. Alguien viene de frente, deprisa.': 'Carrer estret entre els Terrats i els Canals. Algú ve de front, de pressa.',
  'Kai sigue de largo. Dos rangos por delante. No espera respuesta.': 'En Kai segueix de llarg. Dos rangs per davant. No espera resposta.',
  'Eh.': 'Eh.',
  '¿Tú de dónde eres?': 'Tu d\'on ets?',
  '¿Por qué entrenas tanto?': 'Per què entrenes tant?',
  'Te queda bien la marca.': 'Et queda bé la marca.',
  'Nos vemos.': 'Ens veiem.',
  'Sora no está. La taza que dejó anoche sigue donde la dejó. Vacía.': 'La Sora no hi és. La tassa que va deixar ahir nit és on la va deixar. Buida.',
  '«¿Cuánto?» «Hoy no.» «Vale.»': '«Quant?» «Avui no.» «Val.»',
  'La luz entra por la ventana y se apoya en la marca de Iniciado, sobre la mesa.': 'La llum entra per la finestra i es recolza a la marca d\'Iniciat, sobre la taula.',
  '10.000.': '10.000.',
  '100.': '100.',
  'Plano sobre la mesa. Vadic señala un cuadrado de 1 m² y pregunta cuántos cm² entran dentro.': 'Plànol sobre la taula. La Vadic assenyala un quadrat d\'1 m² i pregunta quants cm² hi caben.',
  'Pasillo del Edificio. La Maestra Irune está parada delante de una ventana del archivo.': 'Passadís de l\'Edifici. La Mestra Irune està aturada davant d\'una finestra de l\'arxiu.',
  'Cuando te giras desde el final del patio, ya no está.': 'Quan et gires des del final del pati, ja no hi és.',
  'En el cajón superior, debajo de un trapo doblado, hay una nota. La letra es pequeña.': 'Al calaix superior, sota un drap plegat, hi ha una nota. La lletra és petita.',
  'No da el nombre completo. Solo las iniciales.': 'No dóna el nom complet. Només les inicials.',
  'No hay firma. El niño dobla la nota despacio.': 'No hi ha signatura. El nen plega la nota a poc a poc.',
  'Pero las iniciales son las tuyas, {nombre}.': 'Però les inicials són les teves, {nombre}.',
  'En el Faro de esta semana, una columna corta menciona a un Iniciado de los Tejados que ha cerrado dominios.': 'Al Far d\'aquesta setmana, una columna curta esmenta un Iniciat dels Terrats que ha tancat dominis.',
  'Brina escribió en el Faro que los hay así. Pequeños, tranquilos.': 'La Brina va escriure al Far que n\'hi ha així. Petits, tranquils.',
  'Las dos cosas son verdad.': 'Les dues coses són veritat.',
  'Puentes — puente pequeño': 'Ponts — pont petit',
  'Puentes — mercadillo nocturno': 'Ponts — mercadet nocturn',
  'Puentes — vista a la Montaña': 'Ponts — vista a la Muntanya',
  'Puentes — el pan partido': 'Ponts — el pa partit',
  'Puente pequeño de piedra. El agua baja muy despacio. Faroles lejanos.': 'Pont petit de pedra. L\'aigua baixa molt a poc a poc. Fanalets llunyans.',
  'Puente largo con mercadillo nocturno. Voces bajas, un olor a pan viejo.': 'Pont llarg amb mercadet nocturn. Veus baixes, una olor a pa vell.',
  'Lleva vendiendo aquí desde que yo era joven.': 'Porta venent aquí des que jo era jove.',
  'Nunca ha cambiado los precios.': 'Mai ha canviat els preus.',
  'Compra dos bebidas. Paga con monedas antiguas que el vendedor acepta sin comentar.': 'Compra dues begudes. Paga amb monedes antigues que el venedor accepta sense comentar.',
  'Puente alto. La Montaña al fondo, recortada sobre un cielo limpio.': 'Pont alt. La Muntanya al fons, retallada sobre un cel net.',
  'Rexán se agacha despacio. Saca un pedacito de pan y lo parte en dos.': 'En Rexán s\'ajup a poc a poc. Treu un trosset de pa i el parteix en dos.',
  'Parte una de las mitades otra vez.': 'Parteix una de les meitats una altra vegada.',
  'Un cuarto.': 'Un quart.',
  'Si junto dos cuartos, tengo un medio.': 'Si ajunto dos quarts, tinc un mig.',
  'El camino es al revés, pero el pan sigue siendo el mismo pan.': 'El camí és al revés, però el pa segueix sent el mateix pa.',

  // ═══ Combates: Kurz 1/2/3, Zafrán, Kai, Vorax ═══
