  'OTRO EJEMPLO':
      'UN ALTRE EXEMPLE',
  'Tienen el mismo denominador ({d}): se queda igual.':
      'Tenen el mateix denominador ({d}): es queda igual.',
  'Suma los de arriba: {a} + {b} = {s}.':
      'Suma els de dalt: {a} + {b} = {s}.',
  'Resultado: {r}.':
      'Resultat: {r}.',
  'Busca un denominador que sirva para los dos: {c}.':
      'Busca un denominador que serveixi per als dos: {c}.',
  '{f} = {g}, multiplicando arriba y abajo por {m}.':
      '{f} = {g}, multiplicant a dalt i a baix per {m}.',
  'Ahora suma los de arriba: {a} + {b} = {s}. Resultado: {r}.':
      'Ara suma els de dalt: {a} + {b} = {s}. Resultat: {r}.',
  'Pon las comas una debajo de otra: son décimas.':
      'Posa les comes una sota l\'altra: són dècimes.',
  'Suma las décimas: {a} + {b} = {s} décimas.':
      'Suma les dècimes: {a} + {b} = {s} dècimes.',
  '10 décimas son 1 unidad: {s} décimas = {r}.':
      '10 dècimes són 1 unitat: {s} dècimes = {r}.',
  'Multiplica arriba y abajo por el mismo número, por ejemplo {m}.':
      'Multiplica a dalt i a baix pel mateix nombre, per exemple {m}.',
  'Arriba: {n} × {m} = {a}. Abajo: {d} × {m} = {b}.':
      'A dalt: {n} × {m} = {a}. A baix: {d} × {m} = {b}.',
  '{f} y {g} valen lo mismo.':
      '{f} i {g} valen el mateix.',
  '{f} = {g}.':
      '{f} = {g}.',
  'Busca cuánto hay que multiplicar {d} para llegar a 100: {m}.':
      'Busca per quant cal multiplicar {d} per arribar a 100: {m}.',
  '{c} centésimas se escriben {r}.':
      '{c} centèsimes s\'escriuen {r}.',
  '{c} de cada 100 es el {r}.':
      '{c} de cada 100 és el {r}.',
  'Divide {x} entre {n}: {n} × {q} = {p}.':
      'Divideix {x} entre {n}: {n} × {q} = {p}.',
  'No sobra nada: {x} es múltiplo de {n}.':
      'No sobra res: {x} és múltiple de {n}.',
  'Sobran {r}: {x} no es múltiplo de {n}.':
      'En sobren {r}: {x} no és múltiple de {n}.',
  'Prueba a dividir {x} entre 2, 3, 5 y 7.':
      'Prova de dividir {x} entre 2, 3, 5 i 7.',
  '{x} ÷ {p} = {q}, exacto: no es primo.':
      '{x} ÷ {p} = {q}, exacte: no és primer.',
  'Ninguna división es exacta: {x} es primo.':
      'Cap divisió és exacta: {x} és primer.',
  'Escribe 0,5 como 0,50 para comparar cifra a cifra.':
      'Escriu 0,5 com a 0,50 per comparar xifra a xifra.',
  'Décimas: {a} es mayor que 5, así que {x} es mayor que 0,5.':
      'Dècimes: {a} és més gran que 5, així que {x} és més gran que 0,5.',
  'Décimas: {a} es menor que 5, así que {x} es menor que 0,5.':
      'Dècimes: {a} és més petit que 5, així que {x} és més petit que 0,5.',
  'Las décimas empatan (5): mira las centésimas. {x} es mayor que 0,5.':
      'Les dècimes empaten (5): mira les centèsimes. {x} és més gran que 0,5.',
  'Las décimas empatan (5): mira las centésimas. {x} es igual a 0,5.':
      'Les dècimes empaten (5): mira les centèsimes. {x} és igual a 0,5.',
  'La mitad de {d} es {m}.':
      'La meitat de {d} és {m}.',
  '{n} es más que {m}: {f} es mayor que 1/2.':
      '{n} és més que {m}: {f} és més gran que 1/2.',
  '{n} es menos que {m}: {f} es menor que 1/2.':
      '{n} és menys que {m}: {f} és més petit que 1/2.',
  'Empieza por el mayor y cuenta lo que falta: {m} y {k} más.':
      'Comença pel més gran i compta el que falta: {m} i {k} més.',
  '{m} + {k} = {r}.':
      '{m} + {k} = {r}.',
  'Decenas: {a} + {b} = {s}.':
      'Desenes: {a} + {b} = {s}.',
  'Unidades: {a} + {b} = {s}.':
      'Unitats: {a} + {b} = {s}.',
  'Junta las dos: {a} + {b} = {r}.':
      'Ajunta les dues: {a} + {b} = {r}.',
  'Primero el paréntesis: {a} + {b} = {s}.':
      'Primer el parèntesi: {a} + {b} = {s}.',
  'Luego multiplica: {s} × {c} = {r}.':
      'Després multiplica: {s} × {c} = {r}.',
  'Primero la multiplicación: {b} × {c} = {m}.':
      'Primer la multiplicació: {b} × {c} = {m}.',
  'Luego la suma: {a} + {m} = {r}.':
      'Després la suma: {a} + {m} = {r}.',
  '{e} es {b} × {b} × {b}.':
      '{e} és {b} × {b} × {b}.',
  '{b} × {b} = {c}; {c} × {b} = {r}.':
      '{b} × {b} = {c}; {c} × {b} = {r}.',
  '{e} es {b} × {b} (no {b} × 2).':
      '{e} és {b} × {b} (no {b} × 2).',
  '{b} × {b} = {r}.':
      '{b} × {b} = {r}.',
  'Divide {q} entre {d}: sale {u}. Eso es 1/{d}.':
      'Divideix {q} entre {d}: surt {u}. Això és 1/{d}.',
  'Quieres {n} partes: {u} × {n} = {r}.':
      'En vols {n} parts: {u} × {n} = {r}.',
  'Sólo quieres una parte: {r}.':
      'Només en vols una part: {r}.',
  'El 50 % es la mitad: {q} ÷ 2 = {r}.':
      'El 50 % és la meitat: {q} ÷ 2 = {r}.',
  'El 10 % es dividir entre 10: {q} ÷ 10 = {r}.':
      'El 10 % és dividir entre 10: {q} ÷ 10 = {r}.',
  'El 25 % es la cuarta parte: {q} ÷ 4 = {r}.':
      'El 25 % és la quarta part: {q} ÷ 4 = {r}.',
  'El 25 % es la cuarta parte: {q} ÷ 4 = {t}.':
      'El 25 % és la quarta part: {q} ÷ 4 = {t}.',
  'El 75 % son tres cuartas partes: {t} × 3 = {r}.':
      'El 75 % són tres quartes parts: {t} × 3 = {r}.',
  'El 20 % es el doble: {t} × 2 = {r}.':
      'El 20 % és el doble: {t} × 2 = {r}.',
  'Calcula {p} de cada 100: {q} × {p} ÷ 100 = {r}.':
      'Calcula {p} de cada 100: {q} × {p} ÷ 100 = {r}.',
  // Segunda sala y Engranajes
  'Engranajes':
      'Engranatges',
  'La grúa del Puerto sólo arranca cuando las marcas de sus ruedas coinciden.':
      'La grua del Port només arrenca quan les marques de les rodes coincideixen.',
  'Ruedas de 4 y de 6 dientes. Las marcas no vuelven a juntarse cuando tú crees. Cuéntalo.':
      'Rodes de 4 i de 6 dents. Les marques no es tornen a trobar quan tu et penses. Compta-ho.',
  'Elige un número y mira girar las ruedas. Con las ruedas, busca cuántos dientes tienen que pasar para que las marcas rojas vuelvan arriba a la vez. Con los cabos, el trozo más largo que corta los dos sin que sobre nada. La rueda oxidada esconde sus dientes: descúbrelos.':
      'Tria un nombre i mira girar les rodes. Amb les rodes, busca quantes dents han de passar perquè les marques vermelles tornin a dalt alhora. Amb els caps, el tros més llarg que talla tots dos sense que sobri res. La roda rovellada amaga les dents: descobreix-les.',
  'Trozos de {n} m y no sobra nada. Más largos no salen.':
      'Trossos de {n} m i no sobra res. Més llargs no en surten.',
  'Clac. Las marcas arriba a la vez: la grúa arranca.':
      'Clac. Les marques a dalt alhora: la grua arrenca.',
  'Con {v}, la rueda de {n} no ha dado vueltas enteras: su marca no está arriba.':
      'Amb {v}, la roda de {n} no ha fet voltes senceres: la seva marca no és a dalt.',
  'Coinciden en {v}, sí. Pero antes ya se habían juntado.':
      'Coincideixen a {v}, sí. Però abans ja s\'havien trobat.',
  'Con trozos de {v} m, sobra un pedazo de cabo.':
      'Amb trossos de {v} m, sobra un tros de cap.',
  'Salen iguales y no sobra nada, pero se pueden cortar más largos.':
      'Surten iguals i no sobra res, però es poden tallar més llargs.',
  'Con {v} dientes coincidirían tras {m}, no tras {c}.':
      'Amb {v} dents coincidirien després de {m}, no després de {c}.',
  'Ruedas de {a}, {b} y {c} dientes. ¿Tras cuántos dientes vuelven las tres marcas arriba?':
      'Rodes de {a}, {b} i {c} dents. Després de quantes dents tornen les tres marques a dalt?',
  'Ruedas de {a} y {b} dientes. ¿Tras cuántos dientes vuelven las dos marcas arriba?':
      'Rodes de {a} i {b} dents. Després de quantes dents tornen les dues marques a dalt?',
  'Cabos de {a} m y {b} m. ¿Cuánto mide el trozo más largo que corta los dos sin que sobre?':
      'Caps de {a} m i {b} m. Quant fa el tros més llarg que talla tots dos sense que sobri res?',
  'Una rueda de {a} dientes y otra oxidada. Sus marcas coinciden tras {c} dientes. ¿Cuántos dientes tiene la oxidada?':
      'Una roda de {a} dents i una altra de rovellada. Les marques coincideixen després de {c} dents. Quantes dents té la rovellada?',
  'Seis arranques. La grúa ya carga sola; tú a descansar.':
      'Sis arrencades. La grua ja carrega sola; tu, a descansar.',
  'La planta de arriba':
      'La planta de dalt',
  'Aquí arriba están las que enseñan cosas nuevas. Sólo se encienden si vienes preparado.':
      'Aquí dalt hi ha les que ensenyen coses noves. Només s\'encenen si vens preparat.',
  'Se enciende cuando domines: {llaves}.':
      'S\'encén quan dominis: {llaves}.',
  'Máquinas que enseñan cosas nuevas. Sube cuando quieras.':
      'Màquines que ensenyen coses noves. Puja quan vulguis.',
  'Rexán la abre cuando domines bien lo de esta sala. No hay prisa.':
      'Rexán l\'obre quan dominis bé el d\'aquesta sala. No hi ha pressa.',
  'Escribe los múltiplos de cada número hasta encontrar el primero que se repite: 4, 8, 12… y 6, 12… El mínimo común múltiplo es 12.':
      'Escriu els múltiples de cada nombre fins a trobar el primer que es repeteix: 4, 8, 12… i 6, 12… El mínim comú múltiple és 12.',
  'Escribe los divisores de cada número y quédate con el mayor que comparten: 24 y 36 se dividen los dos entre 12.':
      'Escriu els divisors de cada nombre i queda\'t amb el més gran que comparteixen: 24 i 36 es divideixen tots dos entre 12.',
  'Múltiplos de {a}: {lista}.':
      'Múltiples de {a}: {lista}.',
  'El primero que está en las dos listas: {r}.':
      'El primer que és a les dues llistes: {r}.',
  'Divisores de {a}: {lista}.':
      'Divisors de {a}: {lista}.',
  'El mayor que está en las dos listas: {r}.':
      'El més gran que és a les dues llistes: {r}.',
  'Identificar fracciones equivalentes':
      'Identificar fraccions equivalents',
  'Comparar fracción con 1/2':
      'Comparar una fracció amb 1/2',
  'Múltiplos de un número':
      'Múltiples d\'un nombre',
  'Números primos':
      'Nombres primers',
  'Suma básica de enteros pequeños':
      'Suma bàsica d\'enters petits',
  'Jerarquía de operaciones':
      'Jerarquia d\'operacions',
  'Resolver ecuación lineal simple':
      'Resoldre una equació lineal simple',
  'Fracción de una cantidad':
      'Fracció d\'una quantitat',
  'Sumar y restar decimales':
      'Sumar i restar decimals',
  'Sumar fracciones con denominadores distintos':
      'Sumar fraccions amb denominadors diferents',
  'Comparar decimales':
      'Comparar decimals',
  'Potencias de exponente natural':
      'Potències d\'exponent natural',
  'Área de rectángulos y cuadrados':
      'Àrea de rectangles i quadrats',
  // Esclusas
  'Esclusas':
      'Rescloses',
  'Los números bajan por el canal. Mándalos a su esclusa y ordena a los que vienen atados.':
      'Els nombres baixen pel canal. Envia\'ls a la seva resclosa i ordena els que vénen lligats.',
  'Las compuertas de los Canales se han soltado. Tú decides por dónde pasa cada barca, y rápido.':
      'Les comportes dels Canals s\'han deixat anar. Tu decideixes per on passa cada barca, i de pressa.',
  'Las barquitas bajan solas. En la primera tanda, toca la esclusa de su tramo antes de que lleguen abajo. En la segunda vienen atadas de dos en dos: toca la que vale más. En la tercera, de tres en tres: tócalas de la más pequeña a la más grande. Si una llega abajo, Rexán la sube otra vez.':
      'Les barquetes baixen soles. A la primera tanda, toca la resclosa del seu tram abans que arribin a baix. A la segona vénen lligades de dues en dues: toca la que val més. A la tercera, de tres en tres: toca-les de la més petita a la més gran. Si una arriba a baix, Rexán la torna a pujar.',
  'Se te ha escapado. Te la subo otra vez.':
      'Se t\'ha escapat. Te la torno a pujar.',
  'Esa esclusa no es la suya: {b} no está en ese tramo.':
      'Aquesta resclosa no és la seva: {b} no és en aquest tram.',
  '{b} no es la mayor de las dos.':
      '{b} no és la més gran de les dues.',
  'Esa no tocaba: {b} no es la más pequeña de las que quedan. Empieza otra vez.':
      'Aquesta no tocava: {b} no és la més petita de les que queden. Torna a començar.',
  'Ahora vienen atadas de dos en dos. Toca la que vale más.':
      'Ara vénen lligades de dues en dues. Toca la que val més.',
  'Ahora de tres en tres. De la más pequeña a la más grande.':
      'Ara de tres en tres. De la més petita a la més gran.',
  'Tres tandas por las esclusas. El canal queda en calma.':
      'Tres tandes per les rescloses. El canal queda en calma.',
  'Abre la esclusa de su tramo antes de que llegue abajo.':
      'Obre la resclosa del seu tram abans que arribi a baix.',
  'Toca la que vale más.':
      'Toca la que val més.',
  'Tócalas de la más pequeña a la más grande.':
      'Toca-les de la més petita a la més gran.',
  'menos de {u}':
      'menys de {u}',
  'entre {u} y 1':
      'entre {u} i 1',
  'más de 1':
      'més d\'1',
  'Si el de arriba es menor que el de abajo, la fracción es menor que 1; si es mayor, pasa de 1. 7/5 es más que 1 porque 7 > 5.':
      'Si el de dalt és més petit que el de baix, la fracció és més petita que 1; si és més gran, passa d\'1. 7/5 és més que 1 perquè 7 > 5.',
  'Con el mismo denominador, gana el de arriba más grande: 5/8 > 3/8.':
      'Amb el mateix denominador, guanya el de dalt més gran: 5/8 > 3/8.',
  'Con el mismo numerador, gana el denominador más pequeño: 2/3 > 2/5, porque los tercios son trozos más grandes que los quintos.':
      'Amb el mateix numerador, guanya el denominador més petit: 2/3 > 2/5, perquè els terços són trossos més grans que els cinquens.',
  'Multiplica en cruz: para 3/4 y 5/7, 3 × 7 = 21 y 5 × 4 = 20. Gana la del producto mayor: 3/4.':
      'Multiplica en creu: per a 3/4 i 5/7, 3 × 7 = 21 i 5 × 4 = 20. Guanya la del producte més gran: 3/4.',
  'Compáralas de dos en dos, o pásalas todas a decimal (divide arriba entre abajo) y ordénalas.':
      'Compara-les de dues en dues, o passa-les totes a decimal (divideix el de dalt entre el de baix) i ordena-les.',
  'Iguala las cifras con ceros y compara desde la coma: 0,5 = 0,50, y 0,50 > 0,45.':
      'Iguala les xifres amb zeros i compara des de la coma: 0,5 = 0,50, i 0,50 > 0,45.',
  'Compara el de arriba con el de abajo: {n} y {d}.':
      'Compara el de dalt amb el de baix: {n} i {d}.',
  '{n} es mayor que {d}: {f} es más que 1.':
      '{n} és més gran que {d}: {f} és més que 1.',
  '{n} es menor que {d}: {f} es menos que 1.':
      '{n} és més petit que {d}: {f} és menys que 1.',
  'Mismo denominador ({d}): mira sólo los de arriba.':
      'Mateix denominador ({d}): mira només els de dalt.',
  '{b} > {a}: {f} es la mayor.':
      '{b} > {a}: {f} és la més gran.',
  'Mismo numerador ({n}): mira los de abajo.':
      'Mateix numerador ({n}): mira els de baix.',
  'Partido en {a}, cada trozo es más grande que partido en {b}: {f} es la mayor.':
      'Partit en {a}, cada tros és més gran que partit en {b}: {f} és la més gran.',
  'Multiplica en cruz: {a} × {d} = {x} y {c} × {b} = {y}.':
      'Multiplica en creu: {a} × {d} = {x} i {c} × {b} = {y}.',
  'El producto mayor va con la fracción mayor: {f}.':
      'El producte més gran va amb la fracció més gran: {f}.',
  '{f} ≈ {v}':
      '{f} ≈ {v}',
  'De menor a mayor: {orden}.':
      'De menor a major: {orden}.',
  'Iguala las cifras con ceros: {a} y {b}0.':
      'Iguala les xifres amb zeros: {a} i {b}0.',
  'Compara las décimas y luego las centésimas: {m} es la mayor.':
      'Compara les dècimes i després les centèsimes: {m} és la més gran.',
  // Planos
  'Planos':
      'Plànols',
  'Redibuja las casas de las Afueras con la medida justa: área, valla y tejados.':
      'Redibuixa les cases dels Afores amb la mida justa: àrea, tanca i teulades.',
  'Se mojaron los planos de las casas nuevas. Tú tienes cuadrícula y lápiz; yo, el sello.':
      'Es van mullar els plànols de les cases noves. Tu tens quadrícula i llapis; jo, el segell.',
  'Arrastra el dedo de una esquina a la otra (o toca dos esquinas) para dibujar la habitación; cada cuadro es 1 m². Abajo ves su área y su valla. Cuando cumpla el encargo, pulsa ENTREGAR. No se construye sobre la maleza.':
      'Arrossega el dit d\'una cantonada a l\'altra (o toca dues cantonades) per dibuixar l\'habitació; cada quadre és 1 m². A baix en veus l\'àrea i la tanca. Quan compleixi l\'encàrrec, prem LLIURAR. No es construeix sobre les males herbes.',
  'Esta maleza crece mientras piensas. No hay prisa, pero no para.':
      'Aquestes males herbes creixen mentre penses. No hi ha pressa, però no s\'aturen.',
  'Ahí hay maleza: no se puede construir encima. Muévelo.':
      'Aquí hi ha males herbes: no s\'hi pot construir a sobre. Mou-lo.',
  'Sellado. Esa casa se puede construir.':
      'Segellat. Aquesta casa es pot construir.',
  'Esa valla mide {p} m, no {P}.':
      'Aquesta tanca fa {p} m, no {P}.',
  'Con {P} m de valla cabe un huerto más grande.':
      'Amb {P} m de tanca hi cap un hort més gran.',
  'Tiene {a} m², sí, pero lleva {p} m de valla. Se puede con menos.':
      'Té {a} m², sí, però porta {p} m de tanca. Es pot fer amb menys.',
  'Ese triángulo tiene {t} m²: la mitad del rectángulo de {a}.':
      'Aquest triangle té {t} m²: la meitat del rectangle de {a}.',
  'Esa habitación tiene {a} m². El encargo pide otra cosa.':
      'Aquesta habitació té {a} m². L\'encàrrec demana una altra cosa.',
  'Una habitación de {v} m².':
      'Una habitació de {v} m².',
  'Una habitación de {v} m² con la menor valla posible.':
      'Una habitació de {v} m² amb la tanca més curta possible.',
  'Con {v} m de valla, el huerto más grande posible.':
      'Amb {v} m de tanca, l\'hort més gran possible.',
  'Un tejado triangular de {v} m²: dibuja el rectángulo que lo contiene.':
      'Una teulada triangular de {v} m²: dibuixa el rectangle que la conté.',
  'Una habitación de {v} dm².':
      'Una habitació de {v} dm².',
  'Seis planos sellados. Las Afueras ya tienen barrio.':
      'Sis plànols segellats. Els Afores ja tenen barri.',
  'Arrastra el dedo de una esquina a la otra.':
      'Arrossega el dit d\'una cantonada a l\'altra.',
  'Rectángulo: {a} m² · Tejado: {t} m²':
      'Rectangle: {a} m² · Teulada: {t} m²',
  'Área: {a} m² · Valla: {p} m':
      'Àrea: {a} m² · Tanca: {p} m',
  'ENTREGAR':
      'LLIURAR',
  'El área de un rectángulo es ancho por alto: 4 × 6 = 24 m². Cuenta los cuadros de una fila y multiplica por las filas.':
      'L\'àrea d\'un rectangle és amplada per alçada: 4 × 6 = 24 m². Compta els quadres d\'una fila i multiplica per les files.',
  'El perímetro es la vuelta entera: suma los cuatro lados. Para la misma área, cuanto más cuadrado, menos valla.':
      'El perímetre és la volta sencera: suma els quatre costats. Per a la mateixa àrea, com més quadrat, menys tanca.',
  'Un triángulo rectángulo es medio rectángulo: base por altura y entre dos. Para 12 m² de tejado, un rectángulo de 24.':
      'Un triangle rectangle és mig rectangle: base per alçada i entre dos. Per a 12 m² de teulada, un rectangle de 24.',
  'Un metro cuadrado tiene 10 × 10 = 100 decímetros cuadrados. Para pasar de dm² a m², divide entre 100.':
      'Un metre quadrat té 10 × 10 = 100 decímetres quadrats. Per passar de dm² a m², divideix entre 100.',
  'Una fila tiene {a} cuadros y hay {h} filas.':
      'Una fila té {a} quadres i hi ha {h} files.',
  'Área: {a} × {h} = {r} m².':
      'Àrea: {a} × {h} = {r} m².',
  '{a} × {b}: valla de {p} m.':
      '{a} × {b}: tanca de {p} m.',
  'La más cuadrada, {a} × {b}, gasta menos valla.':
      'La més quadrada, {a} × {b}, gasta menys tanca.',
  'El rectángulo que lo contiene: {b} × {h} = {r} m².':
      'El rectangle que el conté: {b} × {h} = {r} m².',
  'El triángulo es la mitad: {r} ÷ 2 = {t} m².':
      'El triangle és la meitat: {r} ÷ 2 = {t} m².',
  '1 m² = 10 dm × 10 dm = 100 dm².':
      '1 m² = 10 dm × 10 dm = 100 dm².',
  '{d} ÷ 100 = {m} m².':
      '{d} ÷ 100 = {m} m².',
  // Las redes, Nivelar y La caja negra
  'Las redes':
      'Les xarxes',
  'Elige la red de la que es más fácil sacar un pez ámbar y compruébalo echándola.':
      'Tria la xarxa de la qual és més fàcil treure un peix ambre i comprova-ho llançant-la.',
  'Los pescadores quieren peces ámbar para las farolas. Tú eliges la red; el mar decide cada lance.':
      'Els pescadors volen peixos ambre per als fanals. Tu tries la xarxa; el mar decideix cada llançada.',
  'Toca la red de la que es más probable sacar un pez ámbar: no la que tiene más ámbar, sino la que tiene más ámbar de cada tantos. La máquina la echa veinte veces para comprobarlo. Cuenta tu decisión, no lo que salga. Al final, elige cómo se escribe la probabilidad.':
      'Toca la xarxa de la qual és més probable treure un peix ambre: no la que en té més, sinó la que en té més de cada tants. La màquina la llança vint vegades per comprovar-ho. Compta la teva decisió, no el que surti. Al final, tria com s\'escriu la probabilitat.',
  'Echamos la red veinte veces…':
      'Llancem la xarxa vint vegades…',
  'Esta vez sólo {k} de 20. Mala tanda, buena decisión: {a} de cada {t} era la mejor red.':
      'Aquesta vegada només {k} de 20. Mala tanda, bona decisió: {a} de cada {t} era la millor xarxa.',
  'Buena red: {a} de cada {t}. Han salido {k} ámbar de 20.':
      'Bona xarxa: {a} de cada {t}. N\'han sortit {k} d\'ambre de 20.',
  'Han salido {k} de 20, pero la mejor era la de {ma} de cada {mt}: tocaba a más.':
      'N\'han sortit {k} de 20, però la millor era la de {ma} de cada {mt}: en tocaven més.',
  '{o}: {a} de cada {t}. Da igual cómo se escriba.':
      '{o}: {a} de cada {t}. Tant és com s\'escrigui.',
  '{o} no es {a} de cada {t}. Prueba otra.':
      '{o} no és {a} de cada {t}. Prova\'n una altra.',
  'Seis redes echadas. Hay peces ámbar para todas las farolas del muelle.':
      'Sis xarxes llançades. Hi ha peixos ambre per a tots els fanals del moll.',
  'De {t} peces, {a} son ámbar. ¿Qué probabilidad hay de sacar uno ámbar?':
      'De {t} peixos, {a} són ambre. Quina probabilitat hi ha de treure\'n un d\'ambre?',
  '¿De qué red es más probable sacar un pez ámbar?':
      'De quina xarxa és més probable treure un peix ambre?',
  '{a} ámbar de {t}':
      '{a} ambre de {t}',
  'Nivelar':
      'Anivellar',
  'Lee las pilas de contenedores y reparte la carga: media, mediana y moda.':
      'Llegeix les piles de contenidors i reparteix la càrrega: mitjana, mediana i moda.',
  'Este barco va escorado. Si sabes a qué altura quedaría la carga, lo enderezamos.':
      'Aquest vaixell va escorat. Si saps a quina alçada quedaria la càrrega, l\'adrecem.',
  'Las pilas de contenedores son un gráfico: el eje de la izquierda dice cuántos hay. Lee la pregunta y elige un número. Al acertar, el barco lo demuestra: las pilas se igualan (la media), se ordenan (la mediana) o se ilumina la altura que más se repite (la moda).':
      'Les piles de contenidors són un gràfic: l\'eix de l\'esquerra diu quants n\'hi ha. Llegeix la pregunta i tria un nombre. Quan l\'encertes, el vaixell ho demostra: les piles s\'igualen (la mitjana), s\'ordenen (la mediana) o s\'il·lumina l\'alçada que més es repeteix (la moda).',
  'Eso es. Mira: moviendo contenedores, todas quedan igual.':
      'Això mateix. Mira: movent contenidors, totes queden igual.',
  'Ordenadas, la del medio manda.':
      'Ordenades, mana la del mig.',
  'La que más se repite. El barco lo agradece.':
      'La que més es repeteix. El vaixell ho agraeix.',
  'Bien leído.':
      'Ben llegit.',
  'Cuenta otra vez los contenedores de esa pila, con el eje de al lado.':
      'Torna a comptar els contenidors d\'aquesta pila, amb l\'eix del costat.',
  'Resta: la pila alta menos la baja.':
      'Resta: la pila alta menys la baixa.',
  'Con esa altura sobran o faltan contenedores. Suma todos y reparte.':
      'Amb aquesta alçada sobren o falten contenidors. Suma-ho tot i reparteix.',
  'Primero ordénalas de menor a mayor; luego mira la del medio.':
      'Primer ordena-les de menor a major; després mira la del mig.',
  'La moda es la altura que más se repite, no la más alta.':
      'La moda és l\'alçada que més es repeteix, no la més alta.',
  '¿Cuántos contenedores hay en la pila {x}?':
      'Quants contenidors hi ha a la pila {x}?',
  '¿Cuántos contenedores más tiene la pila {x} que la {y}?':
      'Quants contenidors més té la pila {x} que la {y}?',
  'Si igualas todas las pilas moviendo contenedores, ¿a qué altura quedan?':
      'Si iguales totes les piles movent contenidors, a quina alçada queden?',
  'Ordena las pilas de menor a mayor. ¿Cuánto mide la del medio?':
      'Ordena les piles de menor a major. Quant fa la del mig?',
  '¿Qué altura se repite más?':
      'Quina alçada es repeteix més?',
  'Seis cargas repartidas. El barco sale derecho del puerto.':
      'Sis càrregues repartides. El vaixell surt dret del port.',
  'La caja negra':
      'La caixa negra',
  'Entran números y salen otros. Descubre la regla y la caja se abre.':
      'Hi entren nombres i en surten d\'altres. Descobreix la regla i la caixa s\'obre.',
  'Nadie en la Montaña sabe abrirla. Traga números y escupe otros. Tú, a mirar la tabla.':
      'Ningú a la Muntanya no la sap obrir. S\'empassa nombres i n\'escup d\'altres. Tu, a mirar la taula.',
  'La tabla dice qué sale cuando entra cada número. Puedes meter algunos números más para ver qué hace la caja (pocos: piénsalos). Luego te pregunta por un número que no puedes probar. Al final, dos sacos y dos balanzas: ¿cuánto pesa el rojo?':
      'La taula diu què surt quan hi entra cada nombre. Pots posar-hi alguns nombres més per veure què fa la caixa (pocs: pensa-t\'ho). Després et pregunta per un nombre que no pots provar. Al final, dos sacs i dues balances: quant pesa el vermell?',
  'Glup. Ese se lo ha tragado: es un Mudo.':
      'Glup. Aquest se l\'ha empassat: és un Mut.',
  'Clic. La caja se abre.':
      'Clic. La caixa s\'obre.',
  'Con esa respuesta, alguna fila de la tabla no cuadra. Compruébalas todas.':
      'Amb aquesta resposta, alguna fila de la taula no quadra. Comprova-les totes.',
  'Mete {v} en la regla de la tabla: ¿sale {y}?':
      'Posa {v} a la regla de la taula: en surt {y}?',
  'Si el rojo pesa {v}, alguna de las dos balanzas no cuadra.':
      'Si el vermell pesa {v}, alguna de les dues balances no quadra.',
  'Seis cajas abiertas. En la Montaña ya nadie les tiene miedo.':
      'Sis caixes obertes. A la Muntanya ja ningú no els té por.',
  'Si entra {n}, ¿qué sale?':
      'Si hi entra {n}, què en surt?',
  'Ha salido {n}. ¿Qué número entró?':
      'N\'ha sortit {n}. Quin nombre hi va entrar?',
  '¿Cuánto pesa el saco rojo?':
      'Quant pesa el sac vermell?',
  'Prueba números ({n} intentos)':
      'Prova nombres ({n} intents)',
  'ENTRA':
      'ENTRA',
  'SALE':
      'SURT',
  'Probabilidad = casos buenos entre casos posibles. 3 ámbar de 8 es 3/8; 5 de 16 es 5/16. Compara las fracciones, no sólo los ámbar.':
      'Probabilitat = casos bons entre casos possibles. 3 d\'ambre de 8 és 3/8; 5 de 16 és 5/16. Compara les fraccions, no només els d\'ambre.',
  'La misma probabilidad se escribe de tres maneras: 1/4 = 0,25 = 25 %. Divide los buenos entre el total y multiplica por 100 para el %.':
      'La mateixa probabilitat s\'escriu de tres maneres: 1/4 = 0,25 = 25 %. Divideix els bons entre el total i multiplica per 100 per al %.',
  'Lleva la vista de lo alto de la barra al eje de la izquierda: ahí está el número. Para comparar dos barras, resta.':
      'Porta la vista de dalt de la barra a l\'eix de l\'esquerra: allà hi ha el nombre. Per comparar dues barres, resta.',
  'La media es repartir a partes iguales: suma todo y divide entre cuántos hay. 3 + 5 + 7 + 5 = 20, entre 4 = 5.':
      'La mitjana és repartir a parts iguals: suma-ho tot i divideix entre quants n\'hi ha. 3 + 5 + 7 + 5 = 20, entre 4 = 5.',
  'Mediana: ordena de menor a mayor y quédate con el del medio (si son dos, a mitad entre ellos). Moda: el que más se repite.':
      'Mediana: ordena de menor a major i queda\'t amb el del mig (si són dos, a mig camí entre ells). Moda: el que més es repeteix.',
  'Mira cuánto cambia la salida cuando la entrada sube de uno en uno: eso es lo que multiplica. Luego ajusta lo que suma o resta, y comprueba la regla con todas las filas.':
      'Mira quant canvia la sortida quan l\'entrada puja d\'un en un: això és el que multiplica. Després ajusta el que suma o resta, i comprova la regla amb totes les files.',
  'Junta las dos balanzas: si rojo + azul = 13 y rojo − azul = 5, sumándolas quedan dos rojos = 18. Un rojo pesa 9.':
      'Ajunta les dues balances: si vermell + blau = 13 i vermell − blau = 5, sumant-les queden dos vermells = 18. Un vermell pesa 9.',
  'Escribe cada red como fracción: {f} y {g}.':
      'Escriu cada xarxa com a fracció: {f} i {g}.',
  'Gana la del producto mayor: {m}.':
      'Guanya la del producte més gran: {m}.',
  'Como fracción: {f}.':
      'Com a fracció: {f}.',
  'Multiplica arriba y abajo por {m}: {g}.':
      'Multiplica a dalt i a baix per {m}: {g}.',
  'Como decimal, {d}; como porcentaje, {p} %.':
      'Com a decimal, {d}; com a percentatge, {p} %.',
  'La barra A llega a la línea del {a} en el eje; la B, a la del {b}.':
      'La barra A arriba a la línia del {a} a l\'eix; la B, a la del {b}.',
  'A tiene {a} − {b} = {r} más que B.':
      'A en té {a} − {b} = {r} més que B.',
  'Suma todo: {s}.':
      'Suma-ho tot: {s}.',
  'Reparte entre {n}: {s} ÷ {n} = {m}.':
      'Reparteix entre {n}: {s} ÷ {n} = {m}.',
  'Ordena de menor a mayor: {o}.':
      'Ordena de menor a major: {o}.',
  'El del medio (el tercero de cinco) es la mediana: {m}.':
      'El del mig (el tercer de cinc) és la mediana: {m}.',
  'Cada vez que entra uno más, sale {a} más: la regla multiplica por {a}.':
      'Cada vegada que n\'entra un més, en surten {a} més: la regla multiplica per {a}.',
  '{a} × 1 = {p}, pero sale {s}: además suma {b}.':
      '{a} × 1 = {p}, però en surt {s}: a més, suma {b}.',
  'La regla: × {a} y + {b}. Si entra 10, sale {r}.':
      'La regla: × {a} i + {b}. Si hi entra 10, en surt {r}.',
  'Suma las dos: la y se va y quedan dos x = {s}.':
      'Suma-les: la y se\'n va i queden dues x = {s}.',
  'Una x: {s} ÷ 2 = {r}. Y la y: {t} − {r} = {z}.':
      'Una x: {s} ÷ 2 = {r}. I la y: {t} − {r} = {z}.',
  // El pozo y Pinturas
  'El pozo':
      'El pou',
  'El ascensor de la mina baja por debajo de cero. Sigue sus órdenes y di dónde para.':
      'L\'ascensor de la mina baixa per sota de zero. Segueix les seves ordres i digues on s\'atura.',
  'La mina está a oscuras. Si no sabes a qué planta vas, no la encuentras.':
      'La mina és a les fosques. Si no saps a quina planta vas, no la trobes.',
  'Lee las órdenes del ascensor de izquierda a derecha: + sube, − baja. La ficha rosa da la vuelta a la orden siguiente y la azul repite la anterior; −(−5) sube 5. Toca la planta donde acabará. Al final, distancias al suelo: la 7 y la −7 están igual de lejos.':
      'Llegeix les ordres de l\'ascensor d\'esquerra a dreta: + puja, − baixa. La fitxa rosa gira l\'ordre següent i la blava repeteix l\'anterior; −(−5) puja 5. Toca la planta on acabarà. Al final, distàncies a terra: la 7 i la −7 són igual de lluny.',
  'Planta {r}. Justo donde dijiste.':
      'Planta {r}. Just on deies.',
  'La {f} está a {d} plantas del suelo; la {t}, a {e}. La del otro lado es la {r}.':
      'La {f} és a {d} plantes de terra; la {t}, a {e}. La de l\'altre costat és la {r}.',
  'El ascensor para en la {r}, no en la {t}.':
      'L\'ascensor s\'atura a la {r}, no a la {t}.',
  '{r} plantas, pasando por el suelo.':
      '{r} plantes, passant per terra.',
  'Cuenta las plantas de la {a} a la {b}, pasando por el suelo.':
      'Compta les plantes de la {a} a la {b}, passant per terra.',
  'Seis viajes a oscuras sin perderte. La mina ya tiene luz.':
      'Sis viatges a les fosques sense perdre\'t. La mina ja té llum.',
  'Sales de la planta {p}. ¿Dónde acaba el ascensor? Toca la planta.':
      'Surts de la planta {p}. On acaba l\'ascensor? Toca la planta.',
  'Baja o sube a la planta que está a la misma distancia del suelo que la {p}, al otro lado.':
      'Baixa o puja a la planta que és a la mateixa distància de terra que la {p}, a l\'altre costat.',
  '¿Cuántas plantas hay de la {a} a la {b}?':
      'Quantes plantes hi ha de la {a} a la {b}?',
  'invierte la siguiente':
      'gira la següent',
  'repite la anterior':
      'repeteix l\'anterior',
  'Pinturas':
      'Pintures',
  'Prepara los colores de los toldos del Mercado con la receta justa.':
      'Prepara els colors dels tendals del Mercat amb la recepta justa.',
  'Los toldos se han desteñido. Cada puesto trae su receta; si la mezcla no guarda la proporción, el color no sale.':
      'Els tendals s\'han destenyit. Cada parada porta la seva recepta; si la barreja no guarda la proporció, el color no surt.',
  'La receta dice cuánto azul va por cada tanto de amarillo. Elige el cubo que guarda la receta, o pon los botes justos con − y + y pulsa ENTREGAR: el color de la cubeta te dice cómo vas. Al final, la escala del plano y las rebajas.':
      'La recepta diu quant de blau va per cada tant de groc. Tria el galledó que guarda la recepta, o posa els pots justos amb − i + i prem LLIURAR: el color de la cubeta et diu com vas. Al final, l\'escala del plànol i les rebaixes.',
  'Justo: el puesto está a {v} m.':
      'Just: la parada és a {v} m.',
  'Eso cuesta ahora: {v} €.':
      'Això costa ara: {v} €.',
  'El toldo recupera su color.':
      'El tendal recupera el seu color.',
  'Ese cubo no guarda la receta: {a} de azul por cada {b} de amarillo. El Desteñido se come el color.':
      'Aquest galledó no guarda la recepta: {a} de blau per cada {b} de groc. El Destenyit es menja el color.',
  'Con esa cuenta el verde no sale: la receta es {a} de azul por cada {b} de amarillo. Repinta.':
      'Amb aquest compte el verd no surt: la recepta és {a} de blau per cada {b} de groc. Torna a pintar.',
  'Cada centímetro del plano son {k} m. Mide otra vez.':
      'Cada centímetre del plànol són {k} m. Torna a mesurar.',
  'Calcula el {k} % de {p} € y réstalo.':
      'Calcula el {k} % de {p} € i resta\'l.',
  'Seis toldos pintados. El Mercado vuelve a tener color.':
      'Sis tendals pintats. El Mercat torna a tenir color.',
  'Receta: {a} de azul por cada {b} de amarillo. ¿Qué cubo da el mismo color?':
      'Recepta: {a} de blau per cada {b} de groc. Quin galledó dona el mateix color?',
  'Receta {a} : {b}. Hacen falta {t} botes en total. ¿Cuántos de azul?':
      'Recepta {a} : {b}. Calen {t} pots en total. Quants de blau?',
  'Receta {a} : {b}. Ya hay {t} botes de azul. ¿Cuántos de amarillo?':
      'Recepta {a} : {b}. Ja hi ha {t} pots de blau. Quants de groc?',
  'En el plano del Mercado, 1 cm son {k} m. El puesto está a {t} cm. ¿A cuántos metros?':
      'Al plànol del Mercat, 1 cm són {k} m. La parada és a {t} cm. A quants metres?',
  'Un bote de {t} € con un {k} % de descuento. ¿Cuánto cuesta ahora?':
      'Un pot de {t} € amb un {k} % de descompte. Quant costa ara?',
  '{a} azul\n{b} amarillo':
      '{a} blau\n{b} groc',
  'Piensa en plantas: sumar un positivo sube, restar baja. Si estás en la 2 y bajas 7, pasas el suelo: 2 − 7 = −5.':
      'Pensa en plantes: sumar un positiu puja, restar baixa. Si ets a la 2 i baixes 7, passes terra: 2 − 7 = −5.',
  'El valor absoluto es la distancia al suelo, sin mirar si es arriba o abajo: la 7 y la −7 están a 7 plantas. Entre la −4 y la 3 hay 4 + 3 = 7.':
      'El valor absolut és la distància a terra, sense mirar si és a dalt o a baix: la 7 i la −7 són a 7 plantes. Entre la −4 i la 3 n\'hi ha 4 + 3 = 7.',
  'Dos mezclas dan el mismo color si una es la otra multiplicada: 2 : 3 y 4 : 6 sí (×2); 2 : 3 y 4 : 5 no (se sumó 2).':
      'Dues barreges donen el mateix color si una és l\'altra multiplicada: 2 : 3 i 4 : 6 sí (×2); 2 : 3 i 4 : 5 no (es va sumar 2).',
  'Si la receta es 2 : 3, cada tanda tiene 5 botes. Para 15 botes hacen falta 15 ÷ 5 = 3 tandas: 6 de azul y 9 de amarillo.':
      'Si la recepta és 2 : 3, cada tanda té 5 pots. Per a 15 pots calen 15 ÷ 5 = 3 tandes: 6 de blau i 9 de groc.',
  'Regla de tres: si 2 de azul van con 3 de amarillo, 6 de azul (el triple) van con 9 de amarillo (el triple).':
      'Regla de tres: si 2 de blau van amb 3 de groc, 6 de blau (el triple) van amb 9 de groc (el triple).',
  'Un descuento del 25 % es quitar la cuarta parte: de 40 €, 10 € menos, 30 €. Calcula el descuento y réstalo.':
      'Un descompte del 25 % és treure la quarta part: de 40 €, 10 € menys, 30 €. Calcula el descompte i resta\'l.',
  'La escala dice cuánto es cada centímetro del plano: si 1 cm son 5 m, 4 cm son 4 × 5 = 20 m.':
      'L\'escala diu quant és cada centímetre del plànol: si 1 cm són 5 m, 4 cm són 4 × 5 = 20 m.',
  'Desde la {a}, baja {a} plantas y llegas al suelo (0).':
      'Des de la {a}, baixa {a} plantes i arribes a terra (0).',
  'Te quedan {r} por bajar: acabas en la −{r}.':
      'Te\'n queden {r} per baixar: acabes a la −{r}.',
  'De la {a} al suelo hay {x} plantas.':
      'De la {a} a terra hi ha {x} plantes.',
  'Del suelo a la {b}, {b} más: {x} + {b} = {r}.':
      'De terra a la {b}, {b} més: {x} + {b} = {r}.',
  '{a} × {k} = {x} y {b} × {k} = {y}.':
      '{a} × {k} = {x} i {b} × {k} = {y}.',
  'Los dos por el mismo número: misma razón, mismo color.':
      'Tots dos pel mateix nombre: mateixa raó, mateix color.',
  'Cada tanda lleva {a} + {b} = {t} botes.':
      'Cada tanda porta {a} + {b} = {t} pots.',
  '{n} ÷ {t} = {k} tandas.':
      '{n} ÷ {t} = {k} tandes.',
  'Azul: {a} × {k} = {x}. Amarillo: {b} × {k} = {y}.':
      'Blau: {a} × {k} = {x}. Groc: {b} × {k} = {y}.',
  'De {a} a {x} se ha multiplicado por {k}.':
      'De {a} a {x} s\'ha multiplicat per {k}.',
  'El otro, igual: {b} × {k} = {y}.':
      'L\'altre, igual: {b} × {k} = {y}.',
  'El {p} % de {x} € es {d} €.':
      'El {p} % de {x} € és {d} €.',
  'Se resta: {x} − {d} = {r} €.':
      'Es resta: {x} − {d} = {r} €.',
  'Cada centímetro son {e} m.':
      'Cada centímetre són {e} m.',
  '{c} × {e} = {r} m.':
      '{c} × {e} = {r} m.',
  // Rebote y El taller del relojero
  'Rebote':
      'Rebot',
  'Mide ángulos, dispara el láser para que rebote hasta la diana y dibuja reflejos.':
      'Mesura angles, dispara el làser perquè reboti fins a la diana i dibuixa reflexos.',
  'Los focos de la Industria están desviados. La luz rebota como una pelota: sale como llega.':
      'Els focus de la Indústria estan desviats. La llum rebota com una pilota: surt com arriba.',
  'Lee el ángulo en el transportador y di cuánto mide o qué tipo es. En el láser, elige el ángulo para que el rayo rebote en el espejo del suelo y dé en la diana: sale del espejo con el mismo ángulo con el que llega. Cuidado con los Destellos. Al final, toca los cuadros para dibujar el reflejo de la figura y pulsa COMPROBAR.':
      'Llegeix l\'angle al transportador i digues quant fa o de quin tipus és. Al làser, tria l\'angle perquè el raig reboti al mirall de terra i faci diana: surt del mirall amb el mateix angle amb què arriba. Compte amb els Espurnes. Al final, toca els quadres per dibuixar el reflex de la figura i prem COMPROVAR.',
  'Diana. El foco vuelve a su sitio.':
      'Diana. El focus torna al seu lloc.',
  'Sale con {g}°: igual que llegó.':
      'Surt amb {g}°: igual que va arribar.',
  'Medido y apuntado.':
      'Mesurat i apuntat.',
  'Mira dónde empieza el cero del transportador y cuenta desde ahí.':
      'Mira on comença el zero del transportador i compta des d\'allà.',
  'Compáralo con una esquina de papel: el recto mide 90°.':
      'Compara\'l amb una cantonada de paper: el recte fa 90°.',
  'Un Destello se ha tragado la luz. Con {v}° no llega.':
      'Una Espurna s\'ha empassat la llum. Amb {v}° no hi arriba.',
  'Con {v}° el rayo no da en la diana. Prueba otro.':
      'Amb {v}° el raig no fa diana. Prova\'n un altre.',
  'El rayo sale del espejo con el mismo ángulo con el que llega.':
      'El raig surt del mirall amb el mateix angle amb què arriba.',
  'El reflejo, exacto: cada cuadro a la misma distancia del espejo.':
      'El reflex, exacte: cada quadre a la mateixa distància del mirall.',
  'En rosa, los que sobran; con borde, los que faltan. Cada cuadro, a la misma distancia del espejo.':
      'En rosa, els que sobren; amb vora, els que falten. Cada quadre, a la mateixa distància del mirall.',
  'Seis focos en su sitio. La Industria vuelve a tener luz.':
      'Sis focus al seu lloc. La Indústria torna a tenir llum.',
  '¿Cuántos grados mide el ángulo?':
      'Quants graus fa l\'angle?',
  '¿Qué tipo de ángulo es?':
      'Quin tipus d\'angle és?',
  '¿Con qué ángulo hay que disparar para que rebote en el espejo y dé en la diana?':
      'Amb quin angle cal disparar perquè reboti al mirall i faci diana?',
  'El rayo llega al espejo con {g}°. ¿Con qué ángulo sale?':
      'El raig arriba al mirall amb {g}°. Amb quin angle surt?',
  'Dibuja el reflejo de la figura al otro lado del espejo.':
      'Dibuixa el reflex de la figura a l\'altre costat del mirall.',
  'COMPROBAR':
      'COMPROVAR',
  'El taller del relojero':
      'El taller del rellotger',
  'Pesa, llena, corta y pon en hora: los encargos de medida de la Industria.':
      'Pesa, omple, talla i posa en hora: els encàrrecs de mesura de la Indústria.',
  'Aquí se mide todo. Ojo con las etiquetas: la misma pesa puede venir en gramos o en kilos.':
      'Aquí es mesura tot. Compte amb les etiquetes: el mateix pes pot venir en grams o en quilos.',
  'Toca las piezas para ponerlas (y tócalas arriba para quitarlas) hasta tener justo lo que pide el encargo; luego ENTREGAR. No verás el total hasta entregar: calcúlalo. En el reloj, elige qué hora será. 1 kg = 1000 g; 1 l = 1000 ml; 1 m = 100 cm; 1 h = 60 min.':
      'Toca les peces per posar-les (i toca-les a dalt per treure-les) fins a tenir just el que demana l\'encàrrec; després LLIURAR. No veuràs el total fins a lliurar: calcula\'l. Al rellotge, tria quina hora serà. 1 kg = 1000 g; 1 l = 1000 ml; 1 m = 100 cm; 1 h = 60 min.',
  'Justo lo que pedían. Al cliente.':
      'Just el que demanaven. Al client.',
  'Llevas {x}: sobran {d}. Quita algo.':
      'Portes {x}: en sobren {d}. Treu alguna cosa.',
  'Llevas {x}: faltan {d}. Añade algo.':
      'Portes {x}: en falten {d}. Afegeix alguna cosa.',
  'Las {h}. En hora.':
      'Les {h}. En hora.',
  '{o} no. Recuerda: 60 minutos hacen una hora.':
      '{o} no. Recorda: 60 minuts fan una hora.',
  'Seis encargos servidos. El taller cierra a su hora.':
      'Sis encàrrecs servits. El taller tanca a la seva hora.',
  'Corta una varilla de {o}.':
      'Talla una vareta de {o}.',
  'Pon en la báscula {o}.':
      'Posa a la bàscula {o}.',
  'Llena la probeta con {o}.':
      'Omple la proveta amb {o}.',
  'Son las {h}. ¿Qué hora será dentro de {s}?':
      'Són les {h}. Quina hora serà d\'aquí a {s}?',
  'Toca las piezas de abajo para ponerlas.':
      'Toca les peces de baix per posar-les.',
  'Pon el centro del transportador en el vértice y el 0 sobre un lado; lee dónde cae el otro. En un espejo, el rayo sale con el mismo ángulo con el que llega.':
      'Posa el centre del transportador al vèrtex i el 0 sobre un costat; llegeix on cau l\'altre. En un mirall, el raig surt amb el mateix angle amb què arriba.',
  'Agudo: menos de 90°. Recto: 90°, una esquina de papel. Obtuso: entre 90° y 180°. Llano: 180°, una línea recta.':
      'Agut: menys de 90°. Recte: 90°, una cantonada de paper. Obtús: entre 90° i 180°. Pla: 180°, una línia recta.',
  'En un reflejo, cada punto queda a la misma distancia del espejo, pero al otro lado: si está a 2 cuadros, su reflejo también.':
      'En un reflex, cada punt queda a la mateixa distància del mirall, però a l\'altre costat: si és a 2 quadres, el seu reflex també.',
  '1 m = 10 dm = 100 cm. 1,35 m son 1 m y 35 cm: 135 cm.':
      '1 m = 10 dm = 100 cm. 1,35 m són 1 m i 35 cm: 135 cm.',
  '1 kg = 1000 g y 1 l = 1000 ml. 1,75 kg son 1750 g; medio kilo, 500 g; un cuarto, 250 g.':
      '1 kg = 1000 g i 1 l = 1000 ml. 1,75 kg són 1750 g; mig quilo, 500 g; un quart, 250 g.',
  'Suma primero los minutos; si pasan de 60, son una hora más. 10:40 + 35 min = 10:75 = 11:15. Luego suma las horas.':
      'Suma primer els minuts; si passen de 60, és una hora més. 10:40 + 35 min = 10:75 = 11:15. Després suma les hores.',
  'El rayo llega al espejo con {g}°.':
      'El raig arriba al mirall amb {g}°.',
  'Rebota como una pelota: sale con los mismos {g}°, hacia el otro lado.':
      'Rebota com una pilota: surt amb els mateixos {g}°, cap a l\'altre costat.',
  'Compáralo con 90° (una esquina) y con 180° (una recta).':
      'Compara\'l amb 90° (una cantonada) i amb 180° (una recta).',
  '{g}° es menos que 90°: agudo.':
      '{g}° és menys de 90°: agut.',
  '{g}° es justo una esquina: recto.':
      '{g}° és just una cantonada: recte.',
  '{g}° está entre 90° y 180°: obtuso.':
      '{g}° és entre 90° i 180°: obtús.',
  '{g}° es una línea recta: llano.':
      '{g}° és una línia recta: pla.',
  'Un cuadro está a {d} del espejo.':
      'Un quadre és a {d} del mirall.',
  'Su reflejo, a {d} del espejo por el otro lado, en la misma fila.':
      'El seu reflex, a {d} del mirall per l\'altre costat, a la mateixa fila.',
  '100 cm son 1 m.':
      '100 cm són 1 m.',
  '{c} cm = {m} m {r} cm = {d} m.':
      '{c} cm = {m} m {r} cm = {d} m.',
  '1000 g son 1 kg.':
      '1000 g són 1 kg.',
  '{g} g = {k} kg y {r} g = {d} kg.':
      '{g} g = {k} kg i {r} g = {d} kg.',
  'Minutos: {a} + {b} = {t}.':
      'Minuts: {a} + {b} = {t}.',
  '{t} minutos son 1 hora y {r} minutos: las {h}:{m}.':
      '{t} minuts són 1 hora i {r} minuts: les {h}:{m}.',
  // La hornada, El telar y El tranvía
  'La hornada':
      'La fornada',
  'Empaqueta el pan justo: fracciones, impropias, mixtos y bandejas cortadas de otra manera.':
      'Empaqueta el pa just: fraccions, impròpies, mixtes i safates tallades d\'una altra manera.',
  'Sale la hornada de los Tejados. Los pedidos vienen escritos de mil maneras; el pan, cortado de otra.':
      'Surt la fornada de les Teulades. Les comandes vénen escrites de mil maneres; el pa, tallat d\'una altra.',
  'Toca los trozos de pan para meterlos en la caja (y otra vez para sacarlos) hasta tener justo el pedido; luego ENTREGAR. 11/4 son 2 panes y 3 cuartos. Si la bandeja está cortada en octavos y piden 3/4, piensa cuántos octavos son.':
      'Toca els trossos de pa per ficar-los a la caixa (i un altre cop per treure\'ls) fins a tenir just la comanda; després LLIURAR. 11/4 són 2 pans i 3 quarts. Si la safata està tallada en vuitens i demanen 3/4, pensa quants vuitens són.',
  'Ojo, que los Impropios parecen poca cosa.':
      'Compte, que els Impropis semblen poca cosa.',
  'Esta bandeja no está cortada como el pedido. Piénsalo.':
      'Aquesta safata no està tallada com la comanda. Pensa-hi.',
  '{k} trozos de {d}: justo el pedido. A la caja.':
      '{k} trossos de {d}: just la comanda. A la caixa.',
  'Llevas {k} trozos de {d}: te has pasado.':
      'Portes {k} trossos de {d}: t\'has passat.',
  'Llevas {k} trozos de {d}: falta pan.':
      'Portes {k} trossos de {d}: falta pa.',
  '{k} trozos de los {d} de un pan: {k}/{d}.':
      '{k} trossos dels {d} d\'un pa: {k}/{d}.',
  'Cuenta los trozos de la caja (arriba) y en cuántos está cortado el pan (abajo).':
      'Compta els trossos de la caixa (a dalt) i en quants està tallat el pa (a baix).',
  'Seis pedidos servidos. Huele a pan en todos los Tejados.':
      'Sis comandes servides. Fa olor de pa a totes les Teulades.',
  '¿Cuánto pan hay en la caja?':
      'Quant pa hi ha a la caixa?',
  'Pedido: {p} de pan. Toca los trozos para meterlos en la caja.':
      'Comanda: {p} de pa. Toca els trossos per ficar-los a la caixa.',
  'y':
      'i',
  'El telar':
      'El teler',
  'Multiplica y divide fracciones con telas, hilos y cintas.':
      'Multiplica i divideix fraccions amb teles, fils i cintes.',
  'En el telar se cruzan hilos. Lo que se cruza, eso es multiplicar.':
      'Al teler es creuen fils. El que es creua, això és multiplicar.',
  'Lee el encargo y elige el resultado. Al acertar, la tela lo enseña: varias telas juntas, los hilos cruzados (el trozo que se cruza es el resultado), el reparto o las cintas cortadas.':
      'Llegeix l\'encàrrec i tria el resultat. Quan l\'encertes, la tela ho ensenya: diverses teles juntes, els fils creuats (el tros que es creua és el resultat), el repartiment o les cintes tallades.',
  'Lo que se cruza es el resultado: mira la tela.':
      'El que es creua és el resultat: mira la tela.',
  'Cortadas y contadas.':
      'Tallades i comptades.',
  'Tela medida. Al telar.':
      'Tela mesurada. Al teler.',
  'Junta las telas: se suman los trozos, el tamaño del trozo no cambia.':
      'Ajunta les teles: se sumen els trossos, la mida del tros no canvia.',
  'Por fracción: arriba por arriba y abajo por abajo. No se suma nada.':
      'Per fracció: dalt per dalt i baix per baix. No se suma res.',
  'Repartir entre varios hace los trozos más pequeños: el de abajo crece.':
      'Repartir entre diversos fa els trossos més petits: el de baix creix.',
  'Cuenta cuántas cintas de ese largo caben en la tela.':
      'Compta quantes cintes d\'aquesta llargada caben a la tela.',
  'Seis telas tejidas. Las Polillas se quedan sin cena.':
      'Sis teles teixides. Les Arnes es queden sense sopar.',
  '{k} telas de {f} de metro. ¿Cuánta tela en total?':
      '{k} teles de {f} de metre. Quanta tela en total?',
  'Un hilo a {f} del ancho y otro a {g} del alto. ¿Cuánto es {f} × {g}?':
      'Un fil a {f} de l\'amplada i un altre a {g} de l\'alçada. Quant és {f} × {g}?',
  'Reparte {f} de tela entre {k}. ¿Cuánto para cada uno?':
      'Reparteix {f} de tela entre {k}. Quant per a cadascú?',
  '¿Cuántas cintas de 1/{c} de metro salen de {f} de metro?':
      'Quantes cintes d\'1/{c} de metre surten de {f} de metre?',
  'El tranvía':
      'El tramvia',
  'Una línea de tranvía por la recta de los decimales: situar, redondear y pagar el billete.':
      'Una línia de tramvia per la recta dels decimals: situar, arrodonir i pagar el bitllet.',
  'El tranvía para en cada décima. Tú dices dónde; el Revisor, cuánto.':
      'El tramvia para a cada dècima. Tu dius on; el Revisor, quant.',
  'Toca la vía para parar el tranvía en una parada: la pedida, o la más cercana al viajero. Cuando sube un Revisor, elige cuánto cuesta el billete. Cuidado con dónde va la coma.':
      'Toca la via per aturar el tramvia en una parada: la demanada, o la més propera al viatger. Quan puja un Revisor, tria quant costa el bitllet. Compte amb on va la coma.',
  'Sube un Revisor. Billete, por favor.':
      'Puja un Revisor. Bitllet, si us plau.',
  '{v} está más cerca de {r}. Parada.':
      '{v} és més a prop de {r}. Parada.',
  'Parada {r}. Todos abajo.':
      'Parada {r}. Tothom avall.',
  'Paramos en {p}, pero {v} queda más cerca de otra parada.':
      'Parem a {p}, però {v} queda més a prop d\'una altra parada.',
  'Esta es la {p}. Busca la {r}.':
      'Aquesta és la {p}. Busca la {r}.',
  '{o} €. El Revisor se baja contento.':
      '{o} €. El Revisor baixa content.',
  '{o} € no. Mira bien dónde va la coma.':
      '{o} € no. Mira bé on va la coma.',
  'Seis viajes sin perder ni una parada. Última estación.':
      'Sis viatges sense perdre cap parada. Última estació.',
  'Lleva el tranvía a la parada {v}. Toca la vía.':
      'Porta el tramvia a la parada {v}. Toca la via.',
  'El viajero va a {v}. ¿En qué parada (número entero) baja, la más cercana?':
      'El viatger va a {v}. A quina parada (nombre enter) baixa, la més propera?',
  'El viajero va a {v}. ¿En qué parada de décimas baja, la más cercana?':
      'El viatger va a {v}. A quina parada de dècimes baixa, la més propera?',
  'Billete: {k} viajes de {p} €. ¿Cuánto es?':
      'Bitllet: {k} viatges de {p} €. Quant és?',
  'Billete: el {a} del precio de {b} €. ¿Cuánto es?':
      'Bitllet: el {a} del preu de {b} €. Quant és?',
  'Billete: {p} € entre {k} viajeros. ¿Cuánto paga cada uno?':
      'Bitllet: {p} € entre {k} viatgers. Quant paga cadascú?',
  'El de abajo dice en cuántos trozos iguales se corta el pan; el de arriba, cuántos coges. 3/4: pan en 4 trozos, coges 3.':
      'El de baix diu en quants trossos iguals es talla el pa; el de dalt, quants n\'agafes. 3/4: pa en 4 trossos, n\'agafes 3.',
  'Para escribir lo que hay: arriba los trozos que tienes, abajo en cuántos está cortado el pan.':
      'Per escriure el que hi ha: a dalt els trossos que tens, a baix en quants està tallat el pa.',
  'Una impropia tiene más trozos que un pan entero: 11/4 son 8/4 (2 panes) y 3/4. Divide 11 entre 4: 2 y sobran 3.':
      'Una impròpia té més trossos que un pa sencer: 11/4 són 8/4 (2 pans) i 3/4. Divideix 11 entre 4: 2 i en sobren 3.',
  'Un mixto se pasa a trozos: 2 y 3/4 son 2 × 4 + 3 = 11 cuartos.':
      'Un mixt es passa a trossos: 2 i 3/4 són 2 × 4 + 3 = 11 quarts.',
  'Simplificar es juntar trozos: 6/8 = 3/4, dividiendo arriba y abajo entre 2.':
      'Simplificar és ajuntar trossos: 6/8 = 3/4, dividint a dalt i a baix entre 2.',
  'Amplificar es partir los trozos: 3/4 = 6/8, multiplicando arriba y abajo por 2.':
      'Amplificar és partir els trossos: 3/4 = 6/8, multiplicant a dalt i a baix per 2.',
  'Fracción por número: multiplica sólo el de arriba. 3 × 2/5 = 6/5.':
      'Fracció per nombre: multiplica només el de dalt. 3 × 2/5 = 6/5.',
  'Fracción por fracción: arriba por arriba y abajo por abajo. 3/4 × 2/3 = 6/12.':
      'Fracció per fracció: dalt per dalt i baix per baix. 3/4 × 2/3 = 6/12.',
  'Repartir entre un número hace los trozos más pequeños: se multiplica el de abajo. 3/4 entre 3 = 3/12 = 1/4.':
      'Repartir entre un nombre fa els trossos més petits: es multiplica el de baix. 3/4 entre 3 = 3/12 = 1/4.',
  'Cuántas veces cabe: 3/2 entre 1/4 es contar cuartos en tres medios: 6.':
      'Quantes vegades hi cap: 3/2 entre 1/4 és comptar quarts en tres mitjos: 6.',
  'Entre 1 y 2 hay diez décimas: 1,1; 1,2… 1,9. La primera cifra tras la coma son las décimas.':
      'Entre 1 i 2 hi ha deu dècimes: 1,1; 1,2… 1,9. La primera xifra després de la coma són les dècimes.',
  'Para redondear a la décima, mira la centésima: si es 5 o más, sube; si no, se queda. 2,46 → 2,5; 2,43 → 2,4.':
      'Per arrodonir a la dècima, mira la centèsima: si és 5 o més, puja; si no, es queda. 2,46 → 2,5; 2,43 → 2,4.',
  'Multiplica como si no hubiera coma y luego pon tantas cifras decimales como tenía: 3 × 1,25 → 3 × 125 = 375 → 3,75.':
      'Multiplica com si no hi hagués coma i després posa tantes xifres decimals com tenia: 3 × 1,25 → 3 × 125 = 375 → 3,75.',
  'Decimal por decimal: cuenta las cifras decimales de los dos. 0,6 × 2,5 → 6 × 25 = 150 → dos decimales: 1,50.':
      'Decimal per decimal: compta les xifres decimals dels dos. 0,6 × 2,5 → 6 × 25 = 150 → dos decimals: 1,50.',
  'Dividir entre un número: reparte como siempre y pon la coma cuando llegues a ella. 7,5 entre 3 = 2,5.':
      'Dividir entre un nombre: reparteix com sempre i posa la coma quan hi arribis. 7,5 entre 3 = 2,5.',
  'El pan se corta en {d} trozos iguales: eso es el de abajo.':
      'El pa es talla en {d} trossos iguals: això és el de baix.',
  'Se cogen {n}: eso es el de arriba. {n}/{d}.':
      'N\'agafes {n}: això és el de dalt. {n}/{d}.',
  '{n} ÷ {d} = {e} y sobran {r}.':
      '{n} ÷ {d} = {e} i en sobren {r}.',
  '{e} panes enteros y {r}/{d}.':
      '{e} pans sencers i {r}/{d}.',
  'Cada pan son {d} trozos: {e} × {d} = {p}.':
      'Cada pa són {d} trossos: {e} × {d} = {p}.',
  'Más los {r} sueltos: {p} + {r} = {t}. Son {t}/{d}.':
      'Més els {r} solts: {p} + {r} = {t}. Són {t}/{d}.',
  'Arriba y abajo se pueden dividir entre {k}.':
      'A dalt i a baix es poden dividir entre {k}.',
  '{a} ÷ {k} = {n}; {b} ÷ {k} = {d}. Queda {n}/{d}.':
      '{a} ÷ {k} = {n}; {b} ÷ {k} = {d}. Queda {n}/{d}.',
  'De {d} a {e} se multiplica por {k}.':
      'De {d} a {e} es multiplica per {k}.',
  'Arriba igual: {n} × {k} = {r}. {r}/{e}.':
      'A dalt igual: {n} × {k} = {r}. {r}/{e}.',
  '{k} veces {n} trozos: {k} × {n} = {r} trozos.':
      '{k} vegades {n} trossos: {k} × {n} = {r} trossos.',
  'Los trozos siguen siendo de 1/{d}: {r}/{d}.':
      'Els trossos continuen sent d\'1/{d}: {r}/{d}.',
  'Arriba por arriba: {a} × {c} = {x}.':
      'Dalt per dalt: {a} × {c} = {x}.',
  'Abajo por abajo: {b} × {d} = {y}. Resultado: {x}/{y}.':
      'Baix per baix: {b} × {d} = {y}. Resultat: {x}/{y}.',
  'Repartir entre {k} hace cada trozo {k} veces más pequeño.':
      'Repartir entre {k} fa cada tros {k} vegades més petit.',
  'El de abajo se multiplica: {d} × {k} = {e}. Cada uno, {n}/{e}.':
      'El de baix es multiplica: {d} × {k} = {e}. Cadascú, {n}/{e}.',
  'En cada metro caben {c} cintas de 1/{c}.':
      'A cada metre hi caben {c} cintes d\'1/{c}.',
  '{a}/{b} de metro: {a} × {c} ÷ {b} = {r} cintas.':
      '{a}/{b} de metre: {a} × {c} ÷ {b} = {r} cintes.',
  'Está entre {a} y {b}.':
      'És entre {a} i {b}.',
  'Cuenta {d} décimas desde el {a}.':
      'Compta {d} dècimes des del {a}.',
  'Mira la centésima: {c}.':
      'Mira la centèsima: {c}.',
  'Es 5 o más: la décima sube. Queda {r}.':
      'És 5 o més: la dècima puja. Queda {r}.',
  'Es menos de 5: la décima se queda. Queda {r}.':
      'És menys de 5: la dècima es queda. Queda {r}.',
  'Sin coma: {k} × {p} = {r}.':
      'Sense coma: {k} × {p} = {r}.',
  'Dos cifras decimales: {d}.':
      'Dues xifres decimals: {d}.',
  'Sin comas: {a} × {b} = {r}.':
      'Sense comes: {a} × {b} = {r}.',
  'Una decimal más otra: dos cifras decimales, {d}.':
      'Un decimal més un altre: dues xifres decimals, {d}.',
  'Sin coma: {p} ÷ {k} = {r}.':
      'Sense coma: {p} ÷ {k} = {r}.',
  'Tenía una cifra decimal: {d}.':
      'Tenia una xifra decimal: {d}.',
  // Pinturas
  'Multiplica en cruz: {a} × {s} = {x} y {b} × {t} = {y}.':
      'Multiplica en creu: {a} × {s} = {x} i {b} × {t} = {y}.',
  // Depósitos y Andamios
  'Depósitos':
      'Dipòsits',
  'Llena los depósitos de la Industria: cubitos por capas, litros y tapas redondas de tubería.':
      'Omple els dipòsits de la Indústria: cubets per capes, litres i tapes rodones de canonada.',
  'La Industria se calienta. Pide el agua justa: lo que sobra, las Fugas lo tiran al suelo.':
      'La Indústria s\'escalfa. Demana l\'aigua justa: el que sobra, les Fuites ho llencen a terra.',
  'Lee el depósito y elige cuánto cabe. Al acertar se llena capa a capa. Cada capa son largo × ancho cubitos; hay tantas capas como alto. Un litro es un cubo de 10 cm de lado. En las tuberías, la valla es la vuelta (2 × 3,14 × radio) y la tapa, la superficie (3,14 × radio × radio).':
      'Llegeix el dipòsit i tria quant hi cap. Quan l\'encertes s\'omple capa a capa. Cada capa són llarg × ample cubets; hi ha tantes capes com alt. Un litre és un cub de 10 cm de costat. A les canonades, la tanca és la volta (2 × 3,14 × radi) i la tapa, la superfície (3,14 × radi × radi).',
  'Andamios':
      'Bastides',
  'Plataformas cuadradas y escaleras justas para subir a las farolas de la Montaña.':
      'Plataformes quadrades i escales justes per pujar als fanals de la Muntanya.',
  'Arriba sopla. Con la medida justa, los Vértigos no mueven nada.':
      'A dalt bufa. Amb la mida justa, els Vertígens no mouen res.',
  'Elige la medida entre cuatro. La plataforma o la escalera que elijas se dibuja tal cual: si no es justa, no llega, se pasa o se tambalea. El lado de un cuadrado es el número que, multiplicado por sí mismo, da el área. En una escalera apoyada, escalera² = pared² + suelo².':
      'Tria la mida entre quatre. La plataforma o l\'escala que triïs es dibuixa tal qual: si no és justa, no arriba, es passa o trontolla. El costat d\'un quadrat és el nombre que, multiplicat per si mateix, dona l\'àrea. En una escala recolzada, escala² = paret² + terra².',
  'Volumen de una caja: cuenta los cubitos de una capa (largo × ancho) y multiplica por las capas (alto). 4 × 3 × 2 = 24. No se suman.':
      'Volum d\'una caixa: compta els cubets d\'una capa (llarg × ample) i multiplica per les capes (alt). 4 × 3 × 2 = 24. No se sumen.',
  'Con π ≈ 3,14: la vuelta del círculo es 2 × 3,14 × radio; la superficie, 3,14 × radio × radio. Radio 3: vuelta 18,84; superficie 28,26.':
      'Amb π ≈ 3,14: la volta del cercle és 2 × 3,14 × radi; la superfície, 3,14 × radi × radi. Radi 3: volta 18,84; superfície 28,26.',
  'La raíz cuadrada busca el número que, multiplicado por sí mismo, da el que tienes: √49 = 7 porque 7 × 7 = 49. No es la mitad.':
      'L\'arrel quadrada busca el nombre que, multiplicat per si mateix, dona el que tens: √49 = 7 perquè 7 × 7 = 49. No és la meitat.',
  'En un triángulo rectángulo, el lado largo al cuadrado es la suma de los otros dos al cuadrado: 6² + 8² = 36 + 64 = 100 = 10². Sumar 6 + 8 da de más.':
      'En un triangle rectangle, el costat llarg al quadrat és la suma dels altres dos al quadrat: 6² + 8² = 36 + 64 = 100 = 10². Sumar 6 + 8 dona de més.',
  'Una capa: {l} × {a} = {c} cubitos.':
      'Una capa: {l} × {a} = {c} cubets.',
  '{h} capas: {c} × {h} = {v} cubitos.':
      '{h} capes: {c} × {h} = {v} cubets.',
  'Superficie: 3,14 × {r} × {r} = 3,14 × {c}.':
      'Superfície: 3,14 × {r} × {r} = 3,14 × {c}.',
  'Vuelta: 2 × 3,14 × {r} = 6,28 × {r}.':
      'Volta: 2 × 3,14 × {r} = 6,28 × {r}.',
  'Sale {x}.':
      'Surt {x}.',
  'Busca un número que por sí mismo dé {a}.':
      'Busca un nombre que per si mateix doni {a}.',
  '{l} × {l} = {a}: la raíz es {l}.':
      '{l} × {l} = {a}: l\'arrel és {l}.',
  'Al cuadrado: {a}² + {b}² = {x} + {y} = {s}.':
      'Al quadrat: {a}² + {b}² = {x} + {y} = {s}.',
  '¿Qué número por sí mismo da {s}? {c}.':
      'Quin nombre per si mateix dona {s}? {c}.',
  'Capa a capa, lleno hasta arriba.':
      'Capa a capa, ple fins a dalt.',
  'Cada litro es un cubo de 10 cm de lado. Lleno.':
      'Cada litre és un cub de 10 cm de costat. Ple.',
  'Tubería medida. La Industria se enfría.':
      'Canonada mesurada. La Indústria es refreda.',
  'Las Fugas: eso no cabe, se sale por el borde. Cuenta una capa y multiplica por las capas.':
      'Les Fuites: això no hi cap, se surt per la vora. Compta una capa i multiplica per les capes.',
  'Falta agua. Cuenta una capa y multiplica por las capas.':
      'Falta aigua. Compta una capa i multiplica per les capes.',
  'Multiplica las tres medidas y pasa a litros: 1 litro son 1000 cm³.':
      'Multiplica les tres mides i passa a litres: 1 litre són 1000 cm³.',
  'La valla es la vuelta: 2 × 3,14 × el radio. Nada al cuadrado.':
      'La tanca és la volta: 2 × 3,14 × el radi. Res al quadrat.',
  'La tapa es la superficie: 3,14 × el radio × el radio.':
      'La tapa és la superfície: 3,14 × el radi × el radi.',
  'Seis depósitos llenos y ni una gota por el suelo. Las Fugas se secan.':
      'Sis dipòsits plens i ni una gota per terra. Les Fuites s\'assequen.',
  'Un depósito de {l} × {a} × {h} cubitos. ¿Cuántos cubitos caben?':
      'Un dipòsit de {l} × {a} × {h} cubets. Quants cubets hi caben?',
  'Un depósito de {l} × {a} × {h} cm. ¿Cuántos litros caben?':
      'Un dipòsit de {l} × {a} × {h} cm. Quants litres hi caben?',
  'Una tapa de tubería de radio {r} m. ¿Cuántos metros de valla la rodean? (π ≈ 3,14)':
      'Una tapa de canonada de radi {r} m. Quants metres de tanca la volten? (π ≈ 3,14)',
  'Una tapa de tubería de radio {r} m. ¿Cuántos m² de chapa la cubren? (π ≈ 3,14)':
      'Una tapa de canonada de radi {r} m. Quants m² de xapa la cobreixen? (π ≈ 3,14)',
  'Lado justo. La plataforma no se mueve.':
      'Costat just. La plataforma no es mou.',
  'Justa. Ni el viento la mueve. A arreglar la farola.':
      'Justa. Ni el vent la mou. A arreglar el fanal.',
  'La mitad no: busca el número que multiplicado por sí mismo da el área.':
      'La meitat no: busca el nombre que multiplicat per si mateix dona l\'àrea.',
  'Esa plataforma no mide eso. ¿Qué número por sí mismo da el área?':
      'Aquesta plataforma no fa això. Quin nombre per si mateix dona l\'àrea?',
  'Sumar la pared y el suelo da de más: la escalera va en diagonal. Eleva al cuadrado.':
      'Sumar la paret i el terra dona de més: l\'escala va en diagonal. Eleva al quadrat.',
  'Los Vértigos la mueven: no es justa. Escalera² = pared² + suelo².':
      'Els Vertígens la mouen: no és justa. Escala² = paret² + terra².',
  'Restar sin más no vale: suelo² = escalera² − pared².':
      'Restar sense més no val: terra² = escala² − paret².',
  'Así no sube lo que tiene que subir. Suelo² = escalera² − pared².':
      'Així no puja el que ha de pujar. Terra² = escala² − paret².',
  'Seis andamios montados. Las farolas de la Montaña vuelven a dar luz.':
      'Sis bastides muntades. Els fanals de la Muntanya tornen a fer llum.',
  'Una plataforma cuadrada de {a} m². ¿Cuánto mide su lado?':
      'Una plataforma quadrada de {a} m². Quant fa el costat?',
  'La farola está a {h} m de alto y el pie de la escalera, a {b} m de la pared. ¿Qué escalera llega justa?':
      'El fanal és a {h} m d\'alçada i el peu de l\'escala, a {b} m de la paret. Quina escala hi arriba justa?',
  'La escalera mide {c} m y tiene que subir {h} m. ¿A cuántos metros de la pared se apoya?':
      'L\'escala fa {c} m i ha de pujar {h} m. A quants metres de la paret es recolza?',
  // Minas: divisores
  'Las minas: divisores de {n}.':
      'Les mines: divisors de {n}.',
  'Sólo divisores de {n}.':
      'Només divisors de {n}.',
  'Un divisor de 36 cabe en 36 un número exacto de veces: 36 ÷ 9 = 4, así que 9 es divisor. Búscalos por parejas: 1 y 36, 2 y 18, 3 y 12, 4 y 9, 6 y 6. El 24 no: 36 ÷ 24 no es exacto.':
      'Un divisor de 36 hi cap un nombre exacte de vegades: 36 ÷ 9 = 4, així que 9 és divisor. Busca\'ls per parelles: 1 i 36, 2 i 18, 3 i 12, 4 i 9, 6 i 6. El 24 no: 36 ÷ 24 no és exacte.',
  'Busca parejas que multiplicadas den {n}: {p}.':
      'Busca parelles que multiplicades donin {n}: {p}.',
  'Todos los números de las parejas son divisores: {d}.':
      'Tots els nombres de les parelles són divisors: {d}.',
  // Salto: jerarquía con fracciones y decimales
  'Luego la resta: {a} − {b} = {r}.':
      'Després la resta: {a} − {b} = {r}.',
  'Con fracciones, el orden es el mismo: primero × y ÷, luego + y −. 3 + 1/2 × 8: primero 1/2 de 8 = 4, luego 3 + 4 = 7. No (3 + 1/2) × 8.':
      'Amb fraccions, l\'ordre és el mateix: primer × i ÷, després + i −. 3 + 1/2 × 8: primer 1/2 de 8 = 4, després 3 + 4 = 7. No (3 + 1/2) × 8.',
  'Con decimales, lo mismo: primero la multiplicación. 4 + 2,5 × 2: 2,5 × 2 = 5, luego 4 + 5 = 9. Y cuidado con la coma: 2,5 no es 25.':
      'Amb decimals, igual: primer la multiplicació. 4 + 2,5 × 2: 2,5 × 2 = 5, després 4 + 5 = 9. I compte amb la coma: 2,5 no és 25.',
  // Puentes: el puente roto
  'Con el mismo denominador se restan los de arriba y el de abajo se queda: 7/8 − 3/8 = 4/8. El de abajo no se resta.':
      'Amb el mateix denominador es resten els de dalt i el de baix es queda: 7/8 − 3/8 = 4/8. El de baix no es resta.',
  'Con denominadores distintos, pásalas primero al mismo: 3/4 − 1/6 → 9/12 − 2/12 = 7/12.':
      'Amb denominadors diferents, passa-les primer al mateix: 3/4 − 1/6 → 9/12 − 2/12 = 7/12.',
  'Mismo denominador: resta los de arriba, {a} − {b} = {r}.':
      'Mateix denominador: resta els de dalt, {a} − {b} = {r}.',
  'El de abajo se queda: {r}/{d}.':
      'El de baix es queda: {r}/{d}.',
  'Denominador común: {m}. {a}/{b} = {x}/{m} y {c}/{d} = {y}/{m}.':
      'Denominador comú: {m}. {a}/{b} = {x}/{m} i {c}/{d} = {y}/{m}.',
  '{x} − {y} = {r}: queda {r}/{m}.':
      '{x} − {y} = {r}: queda {r}/{m}.',
  'Este puente ha salido largo. Quita justo lo que sobra: lo que mide el puente menos lo que mide el hueco.':
      'Aquest pont ha sortit llarg. Treu just el que sobra: el que fa el pont menys el que fa el forat.',
  // Sin prisas
  'Sin prisas: la pieza espera arriba. Muévela y suéltala cuando lo tengas.':
      'Sense presses: la peça espera a dalt. Mou-la i deixa-la anar quan ho tinguis.',
  // Bestiario: familias de la segunda sala
  'Los Oxidados':
      'Els Oxidats',
  'Puerto, en la grúa':
      'Port, a la grua',
  'Óxido con hambre de dientes. Se meten en los engranajes de la grúa y se comen un diente aquí y otro allá, hasta que las marcas ya no vuelven a coincidir.':
      'Rovell amb gana de dents. Es fiquen als engranatges de la grua i es mengen una dent aquí i una altra allà, fins que les marques ja no tornen a coincidir.',
  'Odian el número que comparten dos ruedas. Por eso lo esconden: quien encuentra el mayor divisor común o el primer múltiplo común los deja sin nada que roer.':
      'Odien el nombre que comparteixen dues rodes. Per això l\'amaguen: qui troba el divisor comú més gran o el primer múltiple comú els deixa sense res per rosegar.',
  'Rexán guarda en un bote una rueda de doce dientes que los Oxidados dejaron en siete. Dice que no la tira porque siete es primo y ya nadie puede quitarle nada más.':
      'En Rexán guarda en un pot una roda de dotze dents que els Oxidats van deixar en set. Diu que no la llença perquè set és primer i ja ningú no li pot treure res més.',
  'Los Signos':
      'Els Signes',
  'Montaña, en la mina':
      'Muntanya, a la mina',
  'Viven por debajo del suelo, donde los números llevan un menos delante. No son números malos: son los que cuentan hacia abajo.':
      'Viuen per sota del terra, on els nombres porten un menys al davant. No són nombres dolents: són els que compten cap avall.',
  'Su truco es esconder el signo. Si bajas de la planta 3 a la −2 y te olvidas del cero, te quedas un piso corto. Los Signos lo saben y te esperan en el rellano.':
      'El seu truc és amagar el signe. Si baixes de la planta 3 a la −2 i t\'oblides del zero, et quedes un pis curt. Els Signes ho saben i t\'esperen al replà.',
  'En la planta más honda de la mina hay una pared con marcas: −1, −2, −3… hasta donde llega la luz. Nadie sabe quién empezó a contar. Nadie ha llegado al final.':
      'A la planta més fonda de la mina hi ha una paret amb marques: −1, −2, −3… fins on arriba la llum. Ningú no sap qui va començar a comptar. Ningú no ha arribat al final.',
  'Los Destellos':
      'Els Esclats',
  'Industria, en los focos':
      'Indústria, als focus',
  'Chispas sueltas que se beben la luz. Si el rayo pasa demasiado cerca, se lo tragan. Se esquivan eligiendo bien el ángulo.':
      'Espurnes soltes que es beuen la llum. Si el raig passa massa a prop, se l\'empassen. S\'esquiven triant bé l\'angle.',
  'La luz rebota en un espejo igual que llega: el mismo ángulo de ida que de vuelta. Los Destellos no lo entienden y se quedan mirando el reflejo, quietos.':
      'La llum rebota en un mirall igual que arriba: el mateix angle d\'anada que de tornada. Els Esclats no ho entenen i es queden mirant el reflex, quiets.',
  'Vadic dice que en Industria hubo un foco que alumbraba en línea recta hasta el mar. Desde que llegaron los Destellos, la luz dobla esquinas. A Vadic no le gusta nada que doble esquinas.':
      'En Vadic diu que a la Indústria hi havia un focus que il·luminava en línia recta fins al mar. D\'ençà que van arribar els Esclats, la llum gira cantonades. A en Vadic no li agrada gens que giri cantonades.',
  'La Maleza':
      'La Mala Herba',
  'Afueras, en los planos':
      'Afores, als plànols',
  'Hierba que brota en las casillas de los planos y no deja construir encima. No muerde. Sólo ocupa sitio.':
      'Herba que brota a les caselles dels plànols i no deixa construir-hi a sobre. No mossega. Només ocupa lloc.',
  'Con la Maleza en medio, 24 metros cuadrados ya no caben como 4 por 6, pero sí como 3 por 8. La misma área, otra forma. La Maleza enseña eso sin querer.':
      'Amb la Mala Herba al mig, 24 metres quadrats ja no hi caben com 4 per 6, però sí com 3 per 8. La mateixa àrea, una altra forma. La Mala Herba ensenya això sense voler.',
  'Las casas de las Afueras se levantaron sobre planos mojados. Por eso algunas tienen un rincón torcido: es donde creció la Maleza y alguien no quiso volver a medir.':
      'Les cases dels Afores es van aixecar sobre plànols mullats. Per això algunes tenen un racó tort: és on va créixer la Mala Herba i algú no va voler tornar a mesurar.',
  'Los Azarosos':
      'Els Atzarosos',
  'Puerto, en el mar':
      'Port, al mar',
  'Peces que cambian de color al saltar. No hacen trampa: son el azar mismo, nadando.':
      'Peixos que canvien de color quan salten. No fan trampa: són l\'atzar mateix, nedant.',
  'Un solo lance no dice nada. Veinte ya cuentan algo. Con la red buena también se puede sacar un pez gris, y eso no quita la razón a quien la eligió.':
      'Una sola calada no diu res. Vint ja expliquen alguna cosa. Amb la xarxa bona també es pot treure un peix gris, i això no treu la raó a qui la va triar.',
  'Los pescadores más viejos del Puerto no apuestan nunca. Cuentan. Dicen que el mar no tiene memoria, pero las libretas sí.':
      'Els pescadors més vells del Port no aposten mai. Compten. Diuen que el mar no té memòria, però les llibretes sí.',
  'El Oleaje':
      'L\'Onatge',
  'Puerto, en los barcos':
      'Port, als vaixells',
  'Olas que llegan cada cierto rato y empujan el barco hacia la pila más alta. Avisan antes. No rompen nada.':
      'Onades que arriben de tant en tant i empenyen el vaixell cap a la pila més alta. Avisen abans. No trenquen res.',
  'Un barco bien cargado deja pasar el Oleaje sin moverse. Para eso hay que saber repartir: la media es lo que tendría cada pila si fueran todas iguales.':
      'Un vaixell ben carregat deixa passar l\'Onatge sense moure\'s. Per a això cal saber repartir: la mitjana és el que tindria cada pila si fossin totes iguals.',
  'Hay capitanes que leen el Oleaje en las pilas de contenedores como quien lee un gráfico. No miran el mar. Miran la carga, y saben.':
      'Hi ha capitans que llegeixen l\'Onatge a les piles de contenidors com qui llegeix un gràfic. No miren el mar. Miren la càrrega, i ho saben.',
  'Los Desteñidos':
      'Els Destenyits',
  'Mercado, en los toldos':
      'Mercat, als tendals',
  'Manchas grises que se comen el color de un toldo cuando la mezcla no guarda la receta. El toldo se queda gris, pero se puede repintar.':
      'Taques grises que es mengen el color d\'un tendal quan la barreja no guarda la recepta. El tendal queda gris, però es pot tornar a pintar.',
  'Dos de azul por tres de amarillo es el mismo verde que cuatro por seis. Los Desteñidos no soportan que el color se mantenga cuando todo crece a la vez.':
      'Dos de blau per tres de groc és el mateix verd que quatre per sis. Els Destenyits no suporten que el color es mantingui quan tot creix alhora.',
  'En el Mercado cuentan que el primer toldo desteñido fue el de un puesto que subió los precios sin avisar. Desde entonces, cada vez que alguien hace trampa con un porcentaje, algo pierde el color.':
      'Al Mercat expliquen que el primer tendal destenyit va ser el d\'una parada que va apujar els preus sense avisar. Des d\'aleshores, cada cop que algú fa trampa amb un percentatge, alguna cosa perd el color.',
  'Los Cambiados':
      'Els Canviats',
  'Industria, en el taller':
      'Indústria, al taller',
  'Piezas con la etiqueta en otra unidad: una pesa de 0,5 kg junto a una de 500 g. Parecen distintas. Son la misma.':
      'Peces amb l\'etiqueta en una altra unitat: un pes de 0,5 kg al costat d\'un de 500 g. Semblen diferents. Són el mateix.',
  'Algunos Cambiados mienten. Uno dice que 1000 cm son un kilómetro, muy serio. Hay que apartarlo sin enfadarse: sólo le falta subir dos peldaños de la escalera.':
      'Alguns Canviats menteixen. Un diu que 1000 cm són un quilòmetre, molt seriós. Cal apartar-lo sense enfadar-se: només li falta pujar dos esglaons de l\'escala.',
  'El relojero del taller tiene un reloj que marca las horas en minutos, otro en segundos y otro en días. Dice que así nunca llega tarde, porque siempre hay uno que va bien.':
      'El rellotger del taller té un rellotge que marca les hores en minuts, un altre en segons i un altre en dies. Diu que així no arriba mai tard, perquè sempre n\'hi ha un que va bé.',
  'Los Mudos':
      'Els Muts',
  'Montaña, en la caja negra':
      'Muntanya, a la caixa negra',
  'Números que la caja negra se traga sin devolver. Cada Mudo cuesta un experimento, y los experimentos se acaban.':
      'Nombres que la caixa negra s\'empassa sense tornar. Cada Mut costa un experiment, i els experiments s\'acaben.',
  'Callan, pero no esconden la regla. Si entra 1 y sale 5, entra 2 y sale 8, la caja suma de tres en tres. Los Mudos sólo esperan a que alguien lo diga en voz alta.':
      'Callen, però no amaguen la regla. Si entra 1 i en surt 5, entra 2 i en surt 8, la caixa suma de tres en tres. Els Muts només esperen que algú ho digui en veu alta.',
  'Nadie en la Montaña sabe quién construyó la caja. Rexán la encontró ya cerrada. Tiene una teoría: dentro no hay nada, sólo una regla. Y una regla no necesita sitio.':
      'Ningú a la Muntanya no sap qui va construir la caixa. En Rexán la va trobar ja tancada. Té una teoria: a dins no hi ha res, només una regla. I una regla no necessita lloc.',
  'Las Polillas':
      'Les Arnes',
  'Mercado, en el telar':
      'Mercat, al teler',
  'Se comen la tela que sobra y dejan agujeros donde no hay que mirar. Si te fijas en los agujeros, te equivocas de cuenta.':
      'Es mengen la tela que sobra i deixen forats on no cal mirar. Si et fixes en els forats, t\'equivoques de compte.',
  'Donde se cruzan dos hilos está la multiplicación: tres cuartos de ancho por dos tercios de alto. Las Polillas nunca muerden ahí. Dicen que sabe raro.':
      'On es creuen dos fils hi ha la multiplicació: tres quarts d\'amplada per dos terços d\'alçada. Les Arnes no hi mosseguen mai. Diuen que té un gust estrany.',
  'La tejedora más vieja del Mercado no tira los retales. Los cose en una manta de trozos iguales. Dice que es la única tela a la que las Polillas no se acercan: está toda contada.':
      'La teixidora més vella del Mercat no llença els retalls. Els cus en una manta de trossos iguals. Diu que és l\'única tela a la qual les Arnes no s\'acosten: està tota comptada.',
  'Los Revisores':
      'Els Revisors',
  'Canales y Mercado, en el tranvía':
      'Canals i Mercat, al tramvia',
  'Suben al tranvía y piden el billete con una cuenta: tres viajes de 1,25, el 0,6 de 2,5, repartir 7,5 entre tres. No multan a nadie. Sólo quieren la cuenta bien hecha.':
      'Pugen al tramvia i demanen el bitllet amb un compte: tres viatges d\'1,25, el 0,6 de 2,5, repartir 7,5 entre tres. No multen ningú. Només volen el compte ben fet.',
  'Su manía es la coma. Si la pones un sitio más allá, el billete cuesta diez veces más, y el Revisor te mira por encima de las gafas sin decir nada.':
      'La seva mania és la coma. Si la poses un lloc més enllà, el bitllet costa deu vegades més, i el Revisor et mira per sobre de les ulleres sense dir res.',
  'El tranvía para en cada décima. Los Revisores se saben todas las paradas de memoria, hasta las que no existen: la 1,45, la 2,999… Dicen que entre dos paradas siempre cabe otra.':
      'El tramvia para a cada dècima. Els Revisors se saben totes les parades de memòria, fins i tot les que no existeixen: l\'1,45, el 2,999… Diuen que entre dues parades sempre n\'hi cap una altra.',
  'Los Vértigos':
      'Els Vertígens',
  'Montaña, en los andamios':
      'Muntanya, a les bastides',
  'Ráfagas de viento que sólo soplan arriba. Si la escalera no es justa, la hacen temblar. Si lo es, pasan de largo.':
      'Ràfegues de vent que només bufen a dalt. Si l\'escala no és justa, la fan tremolar. Si ho és, passen de llarg.',
  'Pared y suelo al cuadrado, sumados, son la escalera al cuadrado. Los Vértigos lo saben desde siempre. Por eso no pueden con un 3, un 4 y un 5.':
      'Paret i terra al quadrat, sumats, són l\'escala al quadrat. Els Vertígens ho saben des de sempre. Per això no poden amb un 3, un 4 i un 5.',
  'Las farolas de la Montaña se apagaron el día que alguien subió con una escalera larga «por si acaso». Rexán lo cuenta a menudo. Nunca dice quién fue.':
      'Els fanals de la Muntanya es van apagar el dia que algú va pujar amb una escala llarga «per si de cas». En Rexán ho explica sovint. No diu mai qui va ser.',
  'Las Fugas':
      'Les Fuites',
  'Industria, en los depósitos':
      'Indústria, als dipòsits',
  'Agujeros que aparecen cuando se pide más agua de la que cabe. Lo que sobra, lo tiran al suelo.':
      'Forats que apareixen quan es demana més aigua de la que hi cap. El que sobra, ho llencen a terra.',
  'Un depósito se llena por capas: largo por ancho cubitos en cada una, y tantas capas como alto. Quien cuenta así nunca pide de más, y las Fugas se secan.':
      'Un dipòsit s\'omple per capes: llarg per ample cubets a cadascuna, i tantes capes com alt. Qui compta així no demana mai de més, i les Fuites s\'assequen.',
  'Las tuberías de la Industria son redondas porque Vadic dice que el círculo es la forma que más agua guarda con menos chapa. Las Fugas prefieren las esquinas.':
      'Les canonades de la Indústria són rodones perquè en Vadic diu que el cercle és la forma que guarda més aigua amb menys xapa. Les Fuites prefereixen les cantonades.',
  // Reto de la semana
  'El reto de la semana':
      'El repte de la setmana',
  'El atasco':
      'L\'embús',
  'Las barcas se han quedado quietas en el canal, de tres en tres. Nada corre: ordénalas de menor a mayor con calma.':
      'Les barques s\'han quedat quietes al canal, de tres en tres. Res no corre: ordena-les de menor a major amb calma.',
  'La rueda loca':
      'La roda boja',
  'Una de las ruedas tiene un número primo de dientes. Es de las cabezotas: casi nunca coincide con la otra.':
      'Una de les rodes té un nombre primer de dents. És de les tossudes: gairebé mai no coincideix amb l\'altra.',
  'Bajo cero':
      'Sota zero',
  'Esta semana la Serpiente sólo come cuentas que cruzan el cero. Cuidado con el signo.':
      'Aquesta setmana la Serp només menja comptes que creuen el zero. Compte amb el signe.',
  'Los puentes rotos':
      'Els ponts trencats',
  'Todos los puentes salen largos. Quita justo lo que sobra.':
      'Tots els ponts surten llargs. Treu just el que sobra.',
  'Tierra de divisores':
      'Terra de divisors',
  'En todos los tableros, las minas son los divisores de un número. Búscalos por parejas.':
      'A tots els taulers, les mines són els divisors d\'un nombre. Busca\'ls per parelles.',
  // Retos de la semana: tres especiales más
  'Sin transportador':
      'Sense transportador',
  'Los ángulos se miden a ojo. Luego aparece el transportador y compruebas. Esta semana no puntúa: es para afinar el ojo.':
      'Els angles es mesuren a ull. Després apareix el transportador i ho comproves. Aquesta setmana no puntua: és per afinar l\'ull.',
  'La doble negación':
      'La doble negació',
  'Todos los viajes llevan un −(−n). Dos noes en la mina significan sí.':
      'Tots els viatges porten un −(−n). Dos nos a la mina volen dir sí.',
  'Casa completa':
      'Casa completa',
  'Tres habitaciones que sumen justo lo que pide el encargo, sin pisarse ni pisar la maleza.':
      'Tres habitacions que sumin just el que demana l\'encàrrec, sense trepitjar-se ni trepitjar la mala herba.',
  'Buen ojo: {g}°.':
      'Bon ull: {g}°.',
  'A ojo engaña. Ahí tienes el transportador: compruébalo y vuelve a elegir.':
      'A ull enganya. Aquí tens el transportador: comprova-ho i torna a triar.',
  'A ojo, sin transportador: ¿cuántos grados mide?':
      'A ull, sense transportador: quants graus fa?',
  'Esa habitación pisa otra. Muévela.':
      'Aquesta habitació en trepitja una altra. Mou-la.',
  'Habitación {n}: {a} m². Llevas {s} m² de {T}.':
      'Habitació {n}: {a} m². Portes {s} m² de {T}.',
  'Las tres suman {s} m², no {T}. Las borro: prueba otra vez.':
      'Les tres sumen {s} m², no {T}. Les esborro: torna-ho a provar.',
  'Casa completa: {T} m² justos. Sellada.':
      'Casa completa: {T} m² justos. Segellada.',
  'Una casa de {v} m² en tres habitaciones, sin pisar maleza.':
      'Una casa de {v} m² en tres habitacions, sense trepitjar mala herba.',
  'Tres casas completas. Rexán las cuelga en la pared.':
      'Tres cases completes. En Rexán les penja a la paret.',
  'PONER LA HABITACIÓN':
      'POSAR L\'HABITACIÓ',
